import React, { useMemo, useState } from "react";
import {
  catalogue,
  filterCatalogue,
  type CatalogueFilters,
} from "./catalogue.js";
import type { Library, Version } from "./research.js";

export function StrategyLibrary({
  library,
  builtins,
  selected,
  inspect,
  compare,
  exportVersion,
  discuss,
  busy = false,
}: {
  library: Library;
  builtins: Version[];
  selected: string[];
  inspect: (v: Version) => void;
  compare: (v: Version) => void;
  exportVersion: (v: Version) => void;
  discuss?: (v: Version) => void;
  busy?: boolean;
}) {
  const [collection, setCollection] = useState("Built-in");
  const [filters, setFilters] = useState<CatalogueFilters>({});
  const entries = useMemo(
    () =>
      catalogue(
        collection === "Built-in" ? builtins : library.versions,
        library.bundles,
      ),
    [collection, builtins, library],
  );
  const visible = filterCatalogue(entries, filters);
  const options = (key: "asset" | "thesis" | "horizonMinutes") =>
    [...new Set(entries.map((e) => String(e[key])))].sort();
  return (
    <>
      <nav aria-label="Library collections">
        {["Built-in", "Mine", "Following", "Public"].map((t) => (
          <button
            key={t}
            aria-pressed={collection === t}
            onClick={() => {
              setCollection(t);
              setFilters({});
            }}
          >
            {t}
          </button>
        ))}
      </nav>
      {["Following", "Public"].includes(collection) ? (
        <p>
          Public discovery is not connected. Private strategies are never
          published by saving.
        </p>
      ) : (
        <>
          <div className="wr-filters" role="group" aria-label="Library filters">
            <label className="wr-search">
              Search strategies
              <input
                type="search"
                maxLength={160}
                value={filters.query ?? ""}
                onChange={(e) =>
                  setFilters((f) => ({ ...f, query: e.target.value }))
                }
              />
            </label>
            {(
              [
                ["asset", "Asset mint", options("asset")],
                ["thesis", "Thesis", options("thesis")],
                ["horizon", "Horizon (minutes)", options("horizonMinutes")],
                [
                  "evidence",
                  "History evidence",
                  ["none", "paper", "historical-replay", "actual"],
                ],
                [
                  "origin",
                  "Record source",
                  [...new Set(entries.map((e) => e.version.origin))].sort(),
                ],
              ] as [keyof CatalogueFilters, string, string[]][]
            ).map(([key, label, values]) => (
              <label key={key}>
                {label}
                <select
                  aria-label={label}
                  value={filters[key] ?? ""}
                  onChange={(e) =>
                    setFilters((f) => ({ ...f, [key]: e.target.value }))
                  }
                >
                  <option value="">All</option>
                  {values.map((v) => (
                    <option key={v} value={v}>
                      {key === "evidence"
                        ? v === "none"
                          ? "No recorded history"
                          : `${v} · unverified import`
                        : v}
                    </option>
                  ))}
                </select>
              </label>
            ))}
            <button onClick={() => setFilters({})}>Reset filters</button>
          </div>
          <p role="status">
            {visible.length} of {entries.length} versions
          </p>
          {visible.length === 0 && <p>No strategies match.</p>}
          <div className="wr-grid">
            {visible.map((e) => (
              <article key={e.version.digest} aria-label={`${e.name} strategy`}>
                <h3>{e.name}</h3>
                <code title={e.version.digest}>
                  {e.version.digest.slice(0, 12)}
                </code>
                <dl className="wr-meta">
                  <dt>Asset mint</dt>
                  <dd>{e.asset}</dd>
                  <dt>Thesis</dt>
                  <dd>{e.thesis}</dd>
                  <dt>Horizon</dt>
                  <dd>{e.horizonMinutes} min</dd>
                  <dt>Source</dt>
                  <dd>{e.version.origin}</dd>
                  <dt>Terms</dt>
                  <dd>{e.document.market.termsHash}</dd>
                  <dt>History</dt>
                  <dd>
                    {e.evidence.length
                      ? `${e.evidence.join(", ")} · unverified import`
                      : "No recorded history"}
                  </dd>
                  <dt>Saved</dt>
                  <dd>
                    <time dateTime={e.version.createdAt}>
                      {e.version.createdAt}
                    </time>
                  </dd>
                  <dt>Weights A–E</dt>
                  <dd>
                    {e.document.allocation.weightsBps
                      .map((w) => `${w / 100}%`)
                      .join(" / ")}
                  </dd>
                </dl>
                <button onClick={() => inspect(e.version)}>
                  Inspect {e.name}
                </button>
                <button
                  onClick={() => compare(e.version)}
                  aria-pressed={selected.includes(e.version.digest)}
                >
                  Compare {e.name}
                </button>
                <button onClick={() => exportVersion(e.version)}>
                  Export {e.name}
                </button>
                {collection === "Mine" && discuss && (
                  <button disabled={busy} onClick={() => discuss(e.version)}>
                    Discuss {e.name}
                  </button>
                )}
              </article>
            ))}
          </div>
        </>
      )}
    </>
  );
}
