import {useEffect,useRef,useState} from 'react';
import {createDraftPreview} from './draft-preview.mjs';
import type {MiningPhaseCase} from './MiningPreview.js';
import data from './mining-preview.json';
export type PreviewEnvelope={schema:string;source:string;execution:'disabled';contextId:string;revision:string|number;expiresAt:number;phaseCase:MiningPhaseCase;binding:Record<string,string>;request:unknown;response:typeof data.scenarios[number]['response'];inputSHA256:string};
export type PreviewInput={phaseCase:MiningPhaseCase;amounts:string[]};
export interface PreviewProvider {preview:(input:PreviewInput,signal:AbortSignal)=>Promise<PreviewEnvelope>;validate:(envelope:PreviewEnvelope,signal:AbortSignal)=>Promise<unknown>}
export type PreviewDisplay={status:string;envelope:PreviewEnvelope|null;error:string|null;refresh:()=>void};
export function useMiningPreview(provider:PreviewProvider|undefined,input:PreviewInput|null){
 const key=JSON.stringify(input),ref=useRef<ReturnType<typeof createDraftPreview>|null>(null);
 const [record,setRecord]=useState<{key:string;status:string;envelope:PreviewEnvelope|null;error:string|null}>({key:'',status:'idle',envelope:null,error:null});
 useEffect(()=>{
  if(!provider||!input)return;
  const session=createDraftPreview(provider,{onChange:(state:any)=>setRecord({key,...state})});ref.current=session;
  const timer=setTimeout(()=>void session.calculate(input),250),expiry=setInterval(()=>session.getState(),500);
  return()=>{clearTimeout(timer);clearInterval(expiry);session.dispose();if(ref.current===session)ref.current=null};
 },[provider,key]);
 const state=record.key===key?record:{status:input?'loading':'idle',envelope:null,error:null};
 const refresh=()=>{if(input)void ref.current?.calculate(input)};
 const review=async()=>{if(!input||!ref.current)throw Error('Calculate the current draft before review.');return ref.current.review(input)};
 return {display:provider?{...state,refresh}:undefined,review};
}
