import React, { useState } from "react";
import {
  acceptStrategy,
  compareScope,
  summarize,
  decimal,
  type Bundle,
  type Version,
} from "./research.js";

export function StrategyCompare({
  versions,
  history,
}: {
  versions: Version[];
  history: Bundle[];
}) {
  const [datasets, setDatasets] = useState<Record<string, number>>({});
  const bundles = versions.map((v) => {
    const b = history[datasets[v.digest]];
    return b?.rows.some((r) => r.strategyDigest === v.digest) ? b : undefined;
  });
  const complete = bundles.length >= 2 && bundles.every(Boolean);
  const comparison = complete ? compareScope(bundles as Bundle[]) : null;
  const settings = versions.map((v) => acceptStrategy(v.raw));
  const summaries = complete
    ? (bundles as Bundle[]).map((b, i) => summarize(b, versions[i].digest))
    : [];
  const configRows = [
    [
      "Weights A–E",
      ...settings.map((s) =>
        s.allocation.weightsBps.map((w) => `${w / 100}%`).join(" / "),
      ),
    ],
    [
      "Turnover cap (SOL)",
      ...settings.map((s) => decimal(s.limits.totalTurnoverLamports)),
    ],
    [
      "Max unsettled (SOL)",
      ...settings.map((s) => decimal(s.limits.maxUnsettledLamports)),
    ],
    [
      "Every nth round",
      ...settings.map((s) => String(s.schedule.everyNthRound)),
    ],
    ["Max rounds", ...settings.map((s) => String(s.schedule.maxRoundsTotal))],
    [
      "Horizon (minutes)",
      ...settings.map((s) => String(s.research.horizonMinutes)),
    ],
  ];
  const table = (rows: string[][], label: string) => (
    <div
      className="wr-table"
      role="region"
      aria-label={`${label} scroll area`}
      tabIndex={0}
    >
      <table aria-label={label}>
        <thead>
          <tr>
            <th>Field</th>
            {versions.map((v) => (
              <th key={v.digest}>
                {acceptStrategy(v.raw).name}
                <br />
                <code title={v.digest}>{v.digest.slice(0, 12)}</code>
              </th>
            ))}
          </tr>
        </thead>
        <tbody>
          {rows.map(([label, ...cells]) => (
            <tr key={label}>
              <th scope="row">{label}</th>
              {cells.map((value, i) => (
                <td key={versions[i].digest}>{value}</td>
              ))}
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
  return (
    <div className="wr-panel">
      <h3>Version comparison</h3>
      {versions.length < 2 ? (
        <p>Select two to four library versions.</p>
      ) : (
        <>
          {versions.map((v) => (
            <label key={v.digest}>
              {acceptStrategy(v.raw).name} dataset
              <select
                aria-label={`${acceptStrategy(v.raw).name} dataset`}
                value={datasets[v.digest] ?? ""}
                onChange={(e) =>
                  setDatasets((d) => ({
                    ...d,
                    [v.digest]: Number(e.target.value),
                  }))
                }
              >
                <option value="" disabled>
                  Select imported dataset
                </option>
                {history.map((b, i) =>
                  b.rows.some((r) => r.strategyDigest === v.digest) ? (
                    <option key={i} value={i}>
                      {b.scope.dataset} · {b.scope.evidence} · import {i + 1}
                    </option>
                  ) : null,
                )}
              </select>
            </label>
          ))}
          {table(configRows, "Strategy settings")}
          <p role="status">
            {comparison
              ? `${comparison.reason}${comparison.differences.length ? `: ${comparison.differences.join(", ")}` : ""}`
              : "Performance unavailable: import history for each selected version."}
          </p>
          {complete && (
            <>
              <h3>Recorded results</h3>
              {table(
                [
                  ...[
                    "market",
                    "terms",
                    "evidence",
                    "from",
                    "to",
                    "dataset",
                    "valuation",
                    "costs",
                    "coverage",
                  ].map((key) => [
                    key,
                    ...bundles.map(
                      (b) => b!.scope[key as keyof Bundle["scope"]],
                    ),
                  ]),
                  ["Verification", ...bundles.map(() => "Unverified import")],
                  [
                    "Gaps",
                    ...bundles.map(
                      (b) => b!.gaps.join("; ") || "None declared",
                    ),
                  ],
                  [
                    "Scope initial bankroll (SOL)",
                    ...bundles.map((b) =>
                      b!.initialBankroll === null
                        ? "Unavailable"
                        : decimal(b!.initialBankroll!),
                    ),
                  ],
                  [
                    "Scope skipped rounds",
                    ...bundles.map((b) =>
                      b!.skipped === null ? "Unavailable" : String(b!.skipped),
                    ),
                  ],
                  [
                    "Scope pending exposure (SOL)",
                    ...bundles.map((b) =>
                      b!.pendingExposure === null
                        ? "Unavailable"
                        : decimal(b!.pendingExposure!),
                    ),
                  ],
                  ...(
                    [
                      ["Finalized mining records", "entries", false],
                      ["Unsettled records", "unsettled", false],
                      ["Committed (SOL)", "committed", true],
                      ["Returned principal (SOL)", "returned", true],
                      ["Fees (SOL)", "fees", true],
                      ["Forfeitures (SOL)", "forfeitures", true],
                      ["User costs (SOL)", "userCosts", true],
                      ["BTC received (base units)", "btcReceived", false],
                      ["BTC pending (base units)", "btcPending", false],
                      ["SAT earned (base units)", "satEarned", false],
                      ["SAT claimed (base units)", "satClaimed", false],
                      ["SAT sold (base units)", "satSold", false],
                      ["BTC sale proceeds (SOL)", "btcSaleSOL", true],
                      ["SAT sale proceeds (SOL)", "satSaleSOL", true],
                      ["Net mining cash flow (SOL)", "netSOL", true],
                      ["Cash-flow drawdown (SOL)", "drawdown", true],
                    ] as [string, keyof ReturnType<typeof summarize>, boolean][]
                  ).map(([label, key, sol]) => [
                    label,
                    ...bundles.map((b, i) => {
                      const value = String(summaries[i][key]);
                      return sol ? decimal(value) : value;
                    }),
                  ]),
                  [
                    "Net per committed turnover",
                    ...bundles.map((b, i) => {
                      const r = summaries[i].perTurnover;
                      return r
                        ? `${decimal(r.numerator)} SOL / ${decimal(r.denominator)} SOL turnover`
                        : "Unavailable: zero committed turnover";
                    }),
                  ],
                  [
                    "SAT acquisition cost",
                    ...bundles.map((b, i) => {
                      const r = summaries[i].costPerSAT;
                      return r
                        ? `${r.numerator} lamports / ${r.denominator} received SAT base units`
                        : "Unavailable: no received SAT";
                    }),
                  ],
                  [
                    "Other receipts (SOL; excluded)",
                    ...bundles.map(
                      (b, i) =>
                        Object.entries(summaries[i].overlays)
                          .map(
                            ([kind, amount]) => `${kind}: ${decimal(amount)}`,
                          )
                          .join("; ") || "None recorded",
                    ),
                  ],
                  [
                    "Marked value",
                    "Unavailable: no market valuation supplied",
                    ...versions
                      .slice(1)
                      .map(() => "Unavailable: no market valuation supplied"),
                  ],
                ],
                "Descriptive recorded results",
              )}
            </>
          )}
          <p>
            Financial replay unavailable: captured terms, observations and
            participation must be supplied together. Imported totals are
            descriptive evidence.
          </p>
        </>
      )}
    </div>
  );
}
