// Display/review lifecycle only. Never authorizes execution or signs transactions.
/** @param {any} provider @param {{now?:()=>number,onChange?:(state:any)=>void}} options */
export function createDraftPreview(provider,{now=()=>Date.now(),onChange=()=>{}}={}){
 let serial=0,abort=null,closed=false,currentKey=null;
 let state={status:'idle',envelope:null,error:null};
 const publish=next=>{state=next;if(!closed)onChange(state)};
 const key=input=>JSON.stringify(input);
 const current=()=>state.envelope&&now()<state.envelope.expiresAt;
 const cancel=()=>{serial++;abort?.abort();abort=null;};
 return {
  getState(){if(state.envelope&&!current())publish({status:'expired',envelope:null,error:'Preview expired. Recalculate before review.'});return state},
  async calculate(input){
   cancel();currentKey=key(input);const ticket=serial,expected=currentKey;abort=new AbortController();
   publish({status:'loading',envelope:null,error:null});
   try{const envelope=await provider.preview(input,abort.signal);if(closed||ticket!==serial||expected!==currentKey)return;
    if(!Number.isSafeInteger(envelope.expiresAt)||envelope.expiresAt<=now())throw Error('Preview context expired.');
    publish({status:'ready',envelope,error:null});
   }catch(e){if(!closed&&ticket===serial)publish({status:'error',envelope:null,error:String(e?.message??e)})}
  },
  invalidate(){cancel();currentKey=null;publish({status:'idle',envelope:null,error:null})},
  async review(input){
   if(currentKey!==key(input)||state.status!=='ready'||!current()) {this.invalidate();throw Error('Recalculate the current allocation before review.')}
   const ticket=serial,envelope=state.envelope;abort=new AbortController();publish({status:'checking',envelope,error:null});
   try{await provider.validate(envelope,abort.signal);
    if(closed||ticket!==serial||currentKey!==key(input))throw Error('Draft changed during review.');
    if(now()>=envelope.expiresAt)throw Error('Preview context expired.');
    publish({status:'ready',envelope,error:null});return envelope;
   }catch(e){if(!closed&&ticket===serial)publish({status:'error',envelope:null,error:String(e?.message??e)});throw e}
  },
  dispose(){cancel();closed=true;currentKey=null;state={status:'idle',envelope:null,error:null}}
 }
}
