import React,{useEffect,useMemo,useState} from 'react';
const decimal=(v:string,places=9)=>{const value=BigInt(v),n=value<0n?-value:value,base=10n**BigInt(places);return `${value<0n?'-':''}${n/base}.${(n%base).toString().padStart(places,'0')}`};
const vaultNames=['Conversion SOL','BTC custody','Buyback USDC','Bridge SOL','Locked SAT','Liquidity SOL','Liquidity SAT'];
const phases=['Reserved','Executed','Reservation released'];
export function TreasuryRecords({treasury,assetMint,roundSlot,receipt,disabled,onInspect,onClear}:{treasury:any;assetMint:string;roundSlot:string;receipt:any;disabled:boolean;onInspect:(request:any)=>Promise<void>;onClear:()=>void}){
 const choices=useMemo(()=>[...treasury.conversions.map((c:any)=>({key:`conversion:${c.value.side}:${c.value.nonce}`,label:`${c.value.side===0?'BTC':'USDC'} conversion ${c.value.nonce}`,selector:{operation:'convert-input',side:c.value.side,nonce:c.value.nonce}})),...treasury.orders.flatMap((o:any)=>o.attempts.flatMap((a:any)=>[o.value.side===0?'execute-buyback':'execute-liquidity',...(a.value.number===o.value.attempts?['expire-order']:[])].map(operation=>({key:`${operation}:${o.value.day}:${o.value.hour}:${a.value.number}`,label:`Day ${o.value.day} · ${o.value.hour}:00 · ${operation==='expire-order'?'Release reservation':o.value.side===0?'Buyback':'Liquidity'} · attempt ${a.value.number}`,selector:{operation,day:o.value.day,hour:o.value.hour,attempt:a.value.number}}))))],[treasury]);
 const [choice,setChoice]=useState(''),[signature,setSignature]=useState('');
 useEffect(()=>{setChoice(choices[0]?.key??'');setSignature('')},[choices]);
 const selected=choices.find(c=>c.key===choice);
 const tokenInfo=(mint:string)=>mint===treasury.state.value.btc_mint?{label:'BTC',decimals:8}:mint===treasury.state.value.usdc_mint?{label:'USDC',decimals:6}:mint===assetMint?{label:'SAT',decimals:9}:mint===treasury.vaults.find((v:any)=>v.kind===0)?.mint?{label:'wSOL',decimals:9}:{label:mint.slice(0,8)+'…',decimals:9};
 const accountName=(address:string)=>address===treasury.state.address?'Treasury':vaultNames[treasury.vaults.find((v:any)=>v.address===address)?.kind]??address.slice(0,8)+'…';
 return <section aria-label="Verified treasury custody"><h3>Protocol treasury</h3><p role="status">{treasury.status==='paused'?'Treasury paused':treasury.status==='order-pending'?'Outstanding reservation':'Treasury records verified'}</p><p>Protocol-owned funds. These balances are not wallet rewards or withdrawal rights.</p><dl className="wt-facts"><div><dt>Unconverted BTC funding SOL</dt><dd>{decimal(treasury.state.value.source_sol[0])}</dd></div><div><dt>Unconverted buyback funding SOL</dt><dd>{decimal(treasury.state.value.source_sol[1])}</dd></div><div><dt>Unwrapped liquidity SOL</dt><dd>{decimal(String(BigInt(treasury.state.value.liquidity_sol)-BigInt(treasury.state.value.liquidity_wrapped)))}</dd></div><div><dt>Reserved buyback USDC</dt><dd>{decimal(treasury.state.value.reserved[0],6)}</dd></div><div><dt>Reserved liquidity SOL</dt><dd>{decimal(treasury.state.value.reserved[1])}</dd></div></dl><div className="wt-table-scroll" tabIndex={0}><table><thead><tr><th>Vault</th><th>Accounted</th><th>Excess</th></tr></thead><tbody>{treasury.vaults.map((v:any)=><tr key={v.kind}><td>{vaultNames[v.kind]}</td><td>{decimal(v.ownedAtoms,v.kind===1?8:v.kind===2?6:9)}</td><td>{decimal(v.excessAtoms,v.kind===1?8:v.kind===2?6:9)}</td></tr>)}</tbody></table></div>
 <h4>Orders · day {treasury.dayId}</h4><p>Includes any outstanding order from an earlier budget. Repeated round views do not add treasury balances.</p><div className="wt-table-scroll" tabIndex={0}><table><thead><tr><th>Day / hour</th><th>Route</th><th>State</th><th>Input</th><th>Locked SAT</th><th>SOL / SAT added</th><th>LP burned</th></tr></thead><tbody>{treasury.orders.map((o:any)=>{const v=o.value;return <tr key={o.address}><td>{v.day} / {v.hour}</td><td>{v.side===0?'Buyback':'Liquidity'}</td><td>{phases[v.phase]}</td><td>{decimal(v.input,v.side===0?6:9)} {v.side===0?'USDC':'SOL'}</td><td>{v.side===0?decimal(v.acquired):'—'}</td><td>{decimal(v.sol_deposited)} / {decimal(v.sat_deposited)}</td><td>{decimal(v.lp_burned)}</td></tr>})}</tbody></table></div>
 {treasury.orders.length===0?<p>No orders in the verified scope.</p>:null}
 <h4>Inspect treasury execution</h4><div className="wt-read-fields"><label>Record<select aria-label="Treasury receipt record" value={choice} onChange={e=>{setChoice(e.target.value);onClear()}}>{choices.map(c=><option key={c.key} value={c.key}>{c.label}</option>)}</select></label><label>Signature<input aria-label="Treasury receipt signature" value={signature} onChange={e=>{setSignature(e.target.value);onClear()}}/></label></div><button disabled={disabled||!selected||!signature} onClick={()=>selected&&void onInspect({roundSlot,signature,...selected.selector})}>Inspect treasury receipt</button>
 {receipt?<section aria-label="Treasury transaction disposition"><h4>{receipt.status==='finalized-success'?(receipt.disposition==='reservation-released'?'Reservation release verified':'Treasury execution verified'):receipt.status==='finalized-failed'?'Treasury transaction failed':receipt.status==='pending'?'Treasury transaction not finalized':'Treasury transaction unavailable'}</h4>{receipt.feeVerified?<dl className="wt-facts"><div><dt>Transaction / account slot</dt><dd>{receipt.slot} / {receipt.currentAccountSlot}</dd></div><div><dt>Submitter network fee SOL</dt><dd>{decimal(receipt.networkFeeLamports)}</dd></div><div><dt>Fee payer</dt><dd style={{overflowWrap:'anywhere'}}>{receipt.payer}</dd></div></dl>:<p>Execution and transaction fee are unverified.</p>}{receipt.receiptProofVerified&&receipt.effects?<section aria-label="Verified treasury effects">{receipt.effects.reservationReleased?<p>Budget reservation released: {decimal(receipt.effects.reservationReleased.amountAtoms,receipt.effects.reservationReleased.asset==='USDC'?6:9)} {receipt.effects.reservationReleased.asset}. No funds transferred.</p>:<><div className="wt-table-scroll" tabIndex={0}><table><thead><tr><th>Account</th><th>Asset</th><th>Transaction change</th></tr></thead><tbody>{receipt.effects.tokenChanges.map((v:any)=>{const token=tokenInfo(v.mint);return <tr key={v.address}><td title={v.address}>{accountName(v.address)}</td><td title={v.mint}>{token.label}</td><td>{decimal(v.deltaAtoms,token.decimals)}</td></tr>})}{receipt.effects.solChanges.map((v:any)=><tr key={'native'+v.address}><td title={v.address}>{accountName(v.address)}</td><td>SOL</td><td>{decimal(v.deltaLamports)}</td></tr>)}</tbody></table></div>{receipt.effects.lpBurnedAtoms!=='0'?<p>LP minted {decimal(receipt.effects.lpMintedAtoms)} · burned {decimal(receipt.effects.lpBurnedAtoms)}</p>:null}</>}</section>:null}<code style={{overflowWrap:'anywhere'}}>{receipt.signature}</code></section>:null}
 </section>;
}
