import {compileAllocation,PRESETS,candidateSlots,validateStrategy} from '../../strategy-contract/src/index.js';
import type {Preset,Strategy,Weights} from '../../strategy-contract/src/index.js';
export {PRESETS};export type {Preset};
export interface Draft {amount:string;preset:Preset;weights:Weights;hours:number;cadence:number;maxRounds:string;turnover:string;unsettled:string;loss:string;fees:string;perFee:string}
export const EMPTY_DRAFT:Draft={amount:'',preset:'center',weights:[500,1500,6000,1500,500],hours:4,cadence:1,maxRounds:'',turnover:'',unsettled:'',loss:'',fees:'',perFee:''};
export function solToLamports(s:string):string {if(!/^(0|[1-9]\d*)(\.\d{1,9})?$/.test(s))throw Error('Enter SOL with at most 9 decimal places.');const [a,b='']=s.split('.');return (BigInt(a)*1000000000n+BigInt(b.padEnd(9,'0'))).toString();}
export function units(n:string):string {const v=BigInt(n);return `${v/1000000000n}.${(v%1000000000n).toString().padStart(9,'0')}`.replace(/\.?0+$/,'')||'0';}
export function allocations(d:Draft):string[]{return compileAllocation(solToLamports(d.amount),d.weights);}
export function fixtureDraft():Draft{return {...EMPTY_DRAFT,amount:'5',preset:'wide',weights:[2000,2000,2000,2000,2000],cadence:3,maxRounds:'8',turnover:'40',unsettled:'10',loss:'4',fees:'0.01',perFee:'0.001'};}
export function strategy(d:Draft):Strategy{
 const count=Number(d.maxRounds);if(!/^\d+$/.test(d.maxRounds))throw Error('Set the maximum rounds.');
 const s:Strategy={schema:'wen-strategy/1',name:'Fixture session draft',description:'Fixture only. Execution disabled.',market:{networkGenesisHash:'fixture-network',programId:'fixture-program',economyId:'fixture-economy',assetMint:'fixture-mint',termsHash:'fixture-terms',interfaceVersion:'fixture-v1'},research:{thesis:'custom',horizonMinutes:60,conditions:[],outlook:null},allocation:{preset:d.preset,weightsBps:d.weights,mode:'fixed',rules:[]},schedule:{startsAt:'2026-10-22T00:00:00Z',expiresAt:`2026-10-22T${String(d.hours).padStart(2,'0')}:00:00Z`,everyNthRound:d.cadence,anchorRound:'0',utcWindows:[],selectedRoundIds:[],skipRoundIds:[],maxRoundsTotal:count,maxRoundsPerUtcDay:count,cooldownRounds:0,randomSelection:null},limits:{perRoundLamports:solToLamports(d.amount),totalTurnoverLamports:solToLamports(d.turnover),dailyTurnoverLamports:solToLamports(d.turnover),maxUnsettledLamports:solToLamports(d.unsettled),maxLossLamports:solToLamports(d.loss),maxUserFeesLamports:solToLamports(d.fees),maxUserFeesPerRoundLamports:solToLamports(d.perFee)},execution:{mode:'review',runner:'browser',mandateId:null}};
 validateStrategy(s);return s;
}
export function schedulePreview(d:Draft){const s=strategy(d);const slots=Array.from({length:d.hours*6},(_,i)=>({roundId:String(i),opensAt:new Date(Date.UTC(2026,9,22,0,i*10)).toISOString().replace('.000Z','Z')}));const candidates=candidateSlots(s.schedule,slots);const selected=candidates.slice(0,s.schedule.maxRoundsTotal);const turnover=BigInt(s.limits.perRoundLamports)*BigInt(selected.length);if(turnover>BigInt(s.limits.totalTurnoverLamports))throw Error('Selected rounds exceed the turnover cap.');return {strategy:s,slots:selected,turnoverLamports:turnover.toString()};}
export function matchesCanonical(d:Draft):boolean{try{return solToLamports(d.amount)==='5000000000'&&d.weights.every(w=>w===2000);}catch{return false;}}
// Exact percentage input; no floating rounding or exponent coercion.
export function percentToBps(s:string):number{if(!/^(0|[1-9]\d*)(\.\d{1,2})?$/.test(s))throw Error('Use a percentage with at most 2 decimal places.');const [whole,fraction='']=s.split('.');const bps=BigInt(whole)*100n+BigInt(fraction.padEnd(2,'0'));if(bps>10000n)throw Error('Percentage must be between 0 and 100.');return Number(bps);}
export function conditionalExample():Strategy{const s=strategy(fixtureDraft());s.name='Inspectable conditional fixture';s.allocation.mode='conditional';s.allocation.rules=[{when:[{metric:'returnBps',lookbackMinutes:60,operator:'gte',valueBps:'5'}],preset:'trend-up',weightsBps:[500,1000,1500,4500,2500]},{when:[{metric:'returnBps',lookbackMinutes:60,operator:'lte',valueBps:'-5'}],preset:'trend-down',weightsBps:[2500,4500,1500,1000,500]}];validateStrategy(s);return s;}
