import React,{useState} from 'react';
import {units} from './state.js';

export function OperatingRecords({operating:o,roundSlot,receipt:r,disabled,onClear,onInspect}:{operating:any;roundSlot:string;receipt:any;disabled:boolean;onClear:()=>void;onInspect:(request:any)=>Promise<void>}){
 const [signature,setSignature]=useState('');
 const v=o.selection,k=o.custody,e=r?.effects;
 const signed=(value:string)=>{const n=BigInt(value);return `${n<0n?'-':''}${units(String(n<0n?-n:n))}`};
 const labels:Record<string,string>={unknown:'Transaction unavailable',pending:'Not finalized','finalized-success':'Operating collection verified','finalized-failed':'Finalized collection failed'};
 return <section aria-label="Verified Operating collection">
  <h3>Operating</h3>
  <span className="wt-tag">{v.collected?'Round collection recorded':v.eligible?'Round collection not recorded':'No collectible round allocation'}</span>
  <dl className="wt-facts">
   <div><dt>Round allocation SOL</dt><dd>{units(v.amountLamports)}</dd></div>
   <div><dt>Exact-entry fees SOL</dt><dd>{units(v.winnerFeesLamports)}</dd></div>
   <div><dt>Forfeiture income SOL</dt><dd>{units(v.forfeitureIncomeLamports)}</dd></div>
   <div><dt>Recorded total collected SOL</dt><dd>{units(k.totalCollectedLamports)}</dd></div>
   <div><dt>Recorded uncollected SOL</dt><dd>{units(k.uncollectedOperatingLamports)}</dd></div>
   <div><dt>Collection recipient</dt><dd style={{overflowWrap:'anywhere'}}>{o.pins.recipient}</dd></div>
  </dl>
  <p>Protocol income, separate from wallet rewards. Totals repeat across round views. Complete cost history and profit are unavailable.</p>
  <label>Signature<input aria-label="Operating receipt signature" value={signature} onChange={event=>{setSignature(event.target.value);onClear()}}/></label>
  <button disabled={disabled||!signature} onClick={()=>void onInspect({roundSlot,signature,operation:'collect'})}>Inspect Operating receipt</button>
  {r?<section aria-label="Operating transaction disposition"><h4>{labels[r.status]}</h4>
   {r.originalTransactionVerified&&e?<><dl className="wt-facts">
    <div><dt>Transaction / account slot</dt><dd>{r.slot} / {r.currentAccountSlot}</dd></div>
    <div><dt>Gross collected SOL</dt><dd>{units(e.amountLamports)}</dd></div>
    <div><dt>Submitter network fee SOL</dt><dd>{units(r.networkFeeLamports)}</dd></div>
    <div><dt>Page rent funded SOL</dt><dd>{units(e.pageRentChargedLamports)}</dd></div>
    <div><dt>Page rent returned SOL</dt><dd>{units(e.pageRentRefundedLamports)}</dd></div>
    <div><dt>Submitter net debit SOL</dt><dd>{signed(e.payerNetDebitLamports)}</dd></div>
    <div><dt>Fee payer</dt><dd style={{overflowWrap:'anywhere'}}>{r.payer}</dd></div>
   </dl><p>Rent remains account capital. The payer address does not establish who bears protocol costs.</p></>:<p>Original execution and costs are unverified.</p>}
  </section>:null}
 </section>;
}
