import React,{useEffect,useRef,useState} from 'react';
import {OperatingRecords} from './OperatingRecords.js';
import {TreasuryRecords} from './TreasuryRecords.js';
import {createDeploymentReadSession,createDeploymentHistorySession} from './deployment-read-session.mjs';
import {units} from './state.js';
export type MiningReadProvider={walletHex:(address:string)=>string;read:(input:any,signal:AbortSignal)=>Promise<any>;receipt:(input:any,signal:AbortSignal)=>Promise<any>;history?:(input:any,signal:AbortSignal)=>Promise<any>;operatingReceipt?:(input:any,signal:AbortSignal)=>Promise<any>;treasuryReceipt?:(input:any,signal:AbortSignal)=>Promise<any>};
export function DeploymentRecords({provider}:{provider:MiningReadProvider}){
 const dispositionLabels:Record<string,string>={unknown:'Transaction unavailable',pending:'Not finalized','finalized-failed':'Finalized transaction failed','finalized-no-payment':'Finalized · no payment'};
 const btcStatus:Record<string,string>={'allocation-pending':'Allocation pending','recovering':'SOL recovery started','ready':'Conversion records verified','awaiting-vaults':'Conversion not initialized'};
 const [includeBtc,setIncludeBtc]=useState(false),[includeStaking,setIncludeStaking]=useState(false),[includeCarry,setIncludeCarry]=useState(false),[includeDaily,setIncludeDaily]=useState(false),[includeTreasury,setIncludeTreasury]=useState(false),[includeOperating,setIncludeOperating]=useState(false);
 const btc=(v:string)=>{const n=BigInt(v);return `${n/100000000n}.${(n%100000000n).toString().padStart(8,'0')}`};
 const [wallet,setWallet]=useState(''),[roundSlot,setRound]=useState(''),[signature,setSignature]=useState(''),[operation,setOperation]=useState('ClaimSol'),[entry,setEntry]=useState('0'),[state,setState]=useState<any>({status:'idle'}),[inputError,setInputError]=useState<string|null>(null);
 const [historyState,setHistoryState]=useState<any>({status:'idle'});
 const history=useRef<ReturnType<typeof createDeploymentHistorySession>|null>(null);
 useEffect(()=>{setHistoryState({status:'idle',page:null,error:null});if(!provider.history)return;const active=createDeploymentHistorySession(provider,{onChange:setHistoryState});history.current=active;const timer=setInterval(()=>active.getState(),1000);return()=>{clearInterval(timer);active.dispose();history.current=null}},[provider]);
 const loadHistory=(cursor:string|null)=>{setInputError(null);try{void history.current?.load({wallet:provider.walletHex(wallet),includeBtc,includeStaking,includeCarry,includeDaily,includeTreasury,includeOperating,cursor})}catch(e){setInputError((e as Error).message)}};
 const session=useRef<ReturnType<typeof createDeploymentReadSession>|null>(null);
 useEffect(()=>{const active=createDeploymentReadSession(provider,{onChange:setState});session.current=active;setState(active.getState());const timer=setInterval(()=>active.getState(),1000);return()=>{clearInterval(timer);active.dispose();session.current=null}},[provider]);
 const selection=()=>({wallet:provider.walletHex(wallet),roundSlot,...(includeBtc?{includeBtc:true}:{}),...(includeStaking?{includeStaking:true}:{}),...(includeCarry?{includeCarry:true}:{}),...(includeDaily?{includeDaily:true}:{}),...(includeTreasury?{includeTreasury:true}:{}),...(includeOperating?{includeOperating:true}:{})});
 const change=(setter:(v:string)=>void,value:string)=>{session.current?.invalidate();history.current?.invalidate();setInputError(null);setter(value)};
 const refresh=()=>{setInputError(null);try{void session.current?.read(selection())}catch(e){setInputError((e as Error).message)}};
 const inspect=async()=>{setInputError(null);try{if(!/^(0|[1-9]\d*)$/.test(entry))throw Error('Enter a valid entry number.');await session.current?.inspect({wallet:provider.walletHex(wallet),roundSlot,signature,operation,entry:Number(entry)})}catch(e){setInputError((e as Error).message)}};
 const snapshot=state.snapshot,receipt=state.receipt;
 return <section className="wt-mining-preview" aria-label="Deployment records">
 <h3>Inspect wallet records</h3><span className="wt-tag">Read only · execution disabled</span>
 <div className="wt-read-fields"><label>Public wallet address<input aria-label="Read wallet address" value={wallet} onChange={e=>change(setWallet,e.target.value)}/></label><label>Round<input aria-label="Read round" inputMode="numeric" value={roundSlot} onChange={e=>change(setRound,e.target.value)}/></label></div>
 <label className="wt-read-toggle"><input type="checkbox" aria-label="Include BTC conversions" checked={includeBtc} onChange={e=>{session.current?.invalidate();history.current?.invalidate();setIncludeBtc(e.target.checked);setOperation('ClaimSol');setInputError(null)}}/> Include BTC conversions</label>
 <label className="wt-read-toggle"><input type="checkbox" aria-label="Include staking rewards" checked={includeStaking} onChange={e=>{session.current?.invalidate();history.current?.invalidate();setIncludeStaking(e.target.checked);setOperation('ClaimSol');setInputError(null)}}/> Include staking rewards</label>
 <label className="wt-read-toggle"><input type="checkbox" aria-label="Include carry rewards" checked={includeCarry} onChange={e=>{session.current?.invalidate();history.current?.invalidate();setIncludeCarry(e.target.checked);setOperation('ClaimSol');setInputError(null)}}/> Include carry rewards</label>
 <label className="wt-read-toggle"><input type="checkbox" aria-label="Include daily prizes" checked={includeDaily} onChange={e=>{session.current?.invalidate();history.current?.invalidate();setIncludeDaily(e.target.checked);setOperation('ClaimSol');setInputError(null)}}/> Include daily prizes</label>
 <label className="wt-read-toggle"><input type="checkbox" aria-label="Include treasury custody" checked={includeTreasury} onChange={e=>{session.current?.invalidate();history.current?.invalidate();setIncludeTreasury(e.target.checked);setOperation('ClaimSol');setInputError(null)}}/> Include treasury custody</label>
 <label className="wt-read-toggle"><input type="checkbox" aria-label="Include Operating collection" checked={includeOperating} onChange={e=>{session.current?.invalidate();history.current?.invalidate();setIncludeOperating(e.target.checked);setOperation('ClaimSol');setInputError(null)}}/> Include Operating collection</label>
 <button onClick={refresh} disabled={state.status==='loading'||state.status==='checking'}>Refresh records</button>
 {provider.history?<section aria-label="Indexed wallet history"><h3>Indexed rounds</h3><button onClick={()=>loadHistory(null)} disabled={historyState.status==='loading'}>Refresh history</button>{historyState.page?.nextCursor?<button onClick={()=>loadHistory(historyState.page.nextCursor)}>Next history page</button>:null}<div role="status">{historyState.status}</div>{historyState.error?<p role="alert">{historyState.error}</p>:null}{historyState.page?<><p>Partial index · separate finalized round snapshots · no combined balance</p><span className="wt-tag">{historyState.page.source==='local-rpc-fixture'?'Simulated RPC · indexed fixture':'Pinned finalized RPC · partial index'}</span><div className="wt-table-scroll" tabIndex={0}><table><thead><tr><th>Round</th><th>Status</th><th>Finalized slot</th><th>Wallet entries</th>{includeStaking?<th>Staking beneficiaries</th>:null}</tr></thead><tbody>{historyState.page.items.map((item:any)=><tr key={item.roundSlot}><td><button onClick={()=>{session.current?.invalidate();setRound(item.roundSlot);setInputError(null)}}>{item.roundSlot}</button></td><td>{item.status==='verified'?'Verified round':'Unavailable or unverified'}</td><td>{item.snapshot?.slot??'—'}</td><td>{item.snapshot?.projection.entries.length??'—'}</td>{includeStaking?<td>{item.snapshot?.staking?.rows.length??'—'}</td>:null}</tr>)}</tbody></table></div>{historyState.page.items.length===0?<p>No indexed rounds. This does not establish an empty wallet history.</p>:null}</>:null}</section>:null}
 <div role="status">{state.status}</div>{state.error||inputError?<p role="alert">{inputError??state.error}</p>:null}
 {snapshot?<><span className="wt-tag">{snapshot.source==='local-rpc-fixture'?'Simulated RPC · local fixture':'Pinned finalized RPC'}</span>
 <dl className="wt-facts"><div><dt>Account table finalized slot</dt><dd>{snapshot.slot}</dd></div><div><dt>Coverage</dt><dd>One settled round · {snapshot.coverage.entryCount} entries checked</dd></div></dl>
 <p>Principal and SAT{includeBtc?' · miner BTC':''}{includeStaking?' · staking rewards':''}{includeCarry?' · carry releases/refunds':''}{includeDaily?' · daily prizes/refunds':''}{includeTreasury?' · protocol treasury':''}{includeOperating?' · Operating collection':''}. Full wallet history is unavailable. RPC data is not an independent state proof.</p>
 <details><summary>Deployment identity</summary><pre style={{whiteSpace:'pre-wrap',overflowWrap:'anywhere'}}>{JSON.stringify(snapshot.identity,null,2)}</pre></details>
 <div className="wt-table-scroll" tabIndex={0} aria-label="Verified round claims"><table><thead><tr><th>Entry</th><th>Committed SOL</th><th>Principal entitled / paid SOL</th><th>Staking refund entitled / paid SOL</th><th>SAT earned / claimed</th></tr></thead><tbody>{snapshot.projection.entries.map((e:any)=><tr key={e.ordinal}><td>{e.ordinal}</td><td>{units(e.committedLamports)}</td><td>{units(e.principalEntitlementLamports)} / {units(e.principalReturnedLamports)}</td><td>{units(e.stakingRefundLamports)} / {units(e.stakingRefundReturnedLamports)}</td><td>{units(e.satAwardedAtoms)} / {units(e.satClaimedAtoms)}</td></tr>)}</tbody></table>{!snapshot.projection.entries.length?<p>No entries for this wallet in this round.</p>:null}</div>
 {snapshot.btc?<section aria-label="Verified BTC conversions"><h3>BTC conversions and payouts</h3><div className="wt-table-scroll" tabIndex={0}><table><thead><tr><th>Entry</th><th>Unsettled input SOL</th><th>Recovered SOL</th><th>BTC acquired</th><th>BTC paid</th><th>BTC unclaimed</th></tr></thead><tbody>{snapshot.projection.payouts.map((p:any)=><tr key={p.ordinal}><td>{p.ordinal}</td><td>{units(p.pendingConversionLamports)}</td><td>{units(p.recoveredLamports)}</td><td>{btc(p.btcAcquiredAtoms)}</td><td>{btc(p.btcPaidAtoms)}</td><td>{btc(p.btcUnclaimedAtoms)}</td></tr>)}</tbody></table></div><span className="wt-tag">{btcStatus[snapshot.btc.status]??'Status unavailable'}</span>{snapshot.btc.state.value.pending?<dl className="wt-facts"><div><dt>Round SOL converted, awaiting allocation</dt><dd>{units(snapshot.btc.unallocatedSpentLamports)}</dd></div><div><dt>Round BTC awaiting allocation</dt><dd>{btc(snapshot.btc.unallocatedBtcAtoms)}</dd></div></dl>:null}</section>:null}
 {snapshot.staking?<section aria-label="Verified staking rewards"><h3>Staking rewards</h3>{['no-eligible-stakers','bootstrap-no-staking','no-staking-allocation'].includes(snapshot.staking.status)?<span className="wt-tag">{snapshot.staking.status==='bootstrap-no-staking'?'Bootstrap · no staking distribution':snapshot.staking.status==='no-staking-allocation'?'No staking reward allocation':'No eligible stake · contributor refunds apply'}</span>:<><span className="wt-tag">Original round beneficiaries · {btcStatus[snapshot.staking.status]}</span><div className="wt-table-scroll" tabIndex={0}><table><thead><tr><th>Beneficiary</th><th>Unsettled input SOL</th><th>Recovered SOL</th><th>BTC acquired</th><th>BTC paid</th><th>BTC unclaimed</th></tr></thead><tbody>{snapshot.staking.rows.map((p:any)=><tr key={p.ordinal}><td>{p.ordinal}</td><td>{units(p.pendingConversionLamports)}</td><td>{units(p.recoveredLamports)}</td><td>{btc(p.btcAcquiredAtoms)}</td><td>{btc(p.btcPaidAtoms)}</td><td>{btc(p.btcUnclaimedAtoms)}</td></tr>)}</tbody></table></div>{snapshot.staking.rows.length===0?<p>No staking beneficiary for this wallet in this round.</p>:null}{snapshot.staking.status==='allocation-pending'?<dl className="wt-facts"><div><dt>Cohort SOL converted, awaiting allocation</dt><dd>{units(snapshot.staking.unallocatedSpentLamports)}</dd></div><div><dt>Cohort BTC awaiting allocation</dt><dd>{btc(snapshot.staking.unallocatedBtcAtoms)}</dd></div></dl>:null}</>}</section>:null}
 {snapshot.carry?<section aria-label="Verified carry rewards"><h3>Carry releases and refunds</h3><p role="status">{({'controller-unavailable':'Carry controller unavailable','decision-unavailable':'Carry decision unavailable',collecting:'Carry held for future rounds',ready:'Carry release finalized','release-allocation-pending':'Beneficiary allocation pending',refundable:'Contributor refunds allocated','refund-allocation-pending':'Contributor allocation pending'} as Record<string,string>)[snapshot.carry.status]}</p>{[['releaseRows','Reserved beneficiary rewards'],['refundRows','Original contributor refunds']].map(([field,label])=><section key={field} aria-label={label}><h4>{label}</h4><div className="wt-table-scroll" tabIndex={0}><table><thead><tr><th>Entry</th><th>SOL entitled / paid</th><th>BTC entitled / paid</th></tr></thead><tbody>{snapshot.carry[field].map((p:any)=><tr key={p.ordinal}><td>{p.ordinal}</td><td>{units(p.solEntitlementLamports)} / {units(p.solPaidLamports)}</td><td>{btc(p.btcEntitlementAtoms)} / {btc(p.btcPaidAtoms)}</td></tr>)}</tbody></table></div>{snapshot.carry[field].length===0?<p>No allocated {field==='releaseRows'?'release':'refund'} record for this wallet.</p>:null}</section>)}</section>:null}
 {snapshot.daily?<section aria-label="Verified daily prizes"><h3>Daily prizes · day {snapshot.daily.dayId}</h3><p role="status">{({'controller-unavailable':'Daily controller unavailable','day-unavailable':'Day record unavailable','scoring-pending':'Scoring pending',reserving:'Prize funding reserved',review:'Public review',correcting:'Score correction in progress',collecting:'Collecting prize funding',allocating:'Prize allocation pending',finalized:'Daily result finalized','refund-allocation-pending':'Contributor allocation pending',refundable:'Contributor refunds allocated'} as Record<string,string>)[snapshot.daily.status]}</p><p>Day awards repeat across this day’s round records; they are the same entitlement.</p>{[['prizeRows','Daily award beneficiaries'],['refundRows','Daily contributor refunds']].map(([field,label])=><section key={field} aria-label={label}><h4>{label}</h4><div className="wt-table-scroll" tabIndex={0}><table><thead><tr><th>{field==='prizeRows'?'Contest / member':'Entry'}</th><th>SOL entitled / paid</th><th>BTC entitled / paid</th></tr></thead><tbody>{snapshot.daily[field].map((p:any)=><tr key={p.ordinal}><td>{field==='prizeRows'?`${p.contestId} / ${p.memberOrdinal}`:p.ordinal}</td><td>{units(p.solEntitlementLamports)} / {units(p.solPaidLamports)}</td><td>{btc(p.btcEntitlementAtoms)} / {btc(p.btcPaidAtoms)}</td></tr>)}</tbody></table></div>{snapshot.daily[field].length===0?<p>No allocated {field==='prizeRows'?'award':'refund'} record for this wallet.</p>:null}</section>)}</section>:null}
 {snapshot.treasury?<TreasuryRecords treasury={snapshot.treasury} assetMint={snapshot.identity.assetMint} roundSlot={roundSlot} receipt={state.treasuryReceipt} disabled={state.status!=='ready'||!provider.treasuryReceipt} onClear={()=>session.current?.clearReceipt()} onInspect={async request=>{setInputError(null);try{await session.current?.inspectTreasury(request)}catch(e){setInputError((e as Error).message)}}}/>:null}
 {snapshot.operating?<OperatingRecords operating={snapshot.operating} roundSlot={roundSlot} receipt={state.operatingReceipt} disabled={state.status!=='ready'||!provider.operatingReceipt} onClear={()=>session.current?.clearReceipt()} onInspect={async request=>{setInputError(null);try{await session.current?.inspectOperating(request)}catch(e){setInputError((e as Error).message)}}}/>:null}
 <h3>Inspect transaction receipt</h3><div className="wt-read-fields"><label>Signature<input aria-label="Receipt signature" value={signature} onChange={e=>{setSignature(e.target.value);session.current?.clearReceipt()}}/></label><label>Operation<select aria-label="Receipt operation" value={operation} onChange={e=>{setOperation(e.target.value);session.current?.clearReceipt()}}><option value="ClaimSol">Principal + staking refund</option><option value="ClaimSat">SAT claim</option>{snapshot.btc?<><option value="ClaimBtc">BTC claim</option><option value="RecoverSol">Unspent SOL recovery</option></>:null}{snapshot.staking?.cohort?<><option value="StakingClaimBtc">Staking BTC claim</option><option value="StakingRecoverSol">Staking SOL recovery</option></>:null}{snapshot.carry?.releaseRows.length?<option value="CarryClaimBtc">Carry BTC release</option>:null}{snapshot.carry?.refundRows.length?<><option value="CarryRefundBtc">Carry BTC refund</option><option value="CarryRefundSol">Carry SOL refund</option></>:null}{snapshot.daily?.prizeRows.length?<><option value="DailyPrizeBtc">Daily prize BTC</option><option value="DailyPrizeSol">Daily prize SOL</option></>:null}{snapshot.daily?.refundRows.length?<><option value="DailyRefundBtc">Daily BTC refund</option><option value="DailyRefundSol">Daily SOL refund</option></>:null}</select></label><label>{operation.startsWith('Staking')?'Beneficiary ordinal':operation.startsWith('DailyPrize')?'Member ordinal':'Entry'}<input aria-label="Receipt entry" inputMode="numeric" value={entry} onChange={e=>{setEntry(e.target.value);session.current?.clearReceipt()}}/></label></div>
 <button onClick={()=>void inspect()} disabled={state.status!=='ready'}>Inspect receipt</button>
 {receipt?.paid===true?<section aria-label="Verified payment receipt"><h3>Verified finalized payment</h3><dl className="wt-facts"><div><dt>Receipt / corroborating account slot</dt><dd>{receipt.slot} / {receipt.currentAccountSlot}</dd></div><div><dt>Principal SOL</dt><dd>{units(receipt.amounts.principalLamports)}</dd></div><div><dt>Staking refund SOL</dt><dd>{units(receipt.amounts.stakingRefundLamports)}</dd></div><div><dt>SAT</dt><dd>{units(receipt.amounts.satAtoms)}</dd></div>{['RecoverSol','StakingRecoverSol','CarryRefundSol','DailyPrizeSol','DailyRefundSol'].includes(receipt.operation)?<div><dt>{receipt.operation==='DailyPrizeSol'?'Daily prize SOL':['CarryRefundSol','DailyRefundSol'].includes(receipt.operation)?'Contributor SOL refund':'Recovered SOL'}</dt><dd>{units(receipt.amounts.recoveredLamports)}</dd></div>:null}{['ClaimBtc','StakingClaimBtc','CarryClaimBtc','CarryRefundBtc','DailyPrizeBtc','DailyRefundBtc'].includes(receipt.operation)?<><div><dt>BTC paid by this transaction</dt><dd>{btc(receipt.amounts.btcAtoms)}</dd></div><div><dt>Cumulative BTC paid</dt><dd>{btc(receipt.cumulativeBtcPaidAtoms)}</dd></div></>:null}<div><dt>User network fee SOL</dt><dd>{units(receipt.amounts.networkFeeLamports)}</dd></div></dl><code style={{overflowWrap:'anywhere'}}>{receipt.signature}</code></section>:null}
 {receipt&&receipt.paid===false?<section aria-label="Transaction disposition"><h3>{dispositionLabels[receipt.status]}</h3><span className="wt-tag">No payment verified</span>{receipt.originalTransactionVerified?<dl className="wt-facts"><div><dt>Signed original</dt><dd>Verified</dd></div><div><dt>Transaction / account slot</dt><dd>{receipt.slot} / {receipt.currentAccountSlot}</dd></div><div><dt>User network fee SOL</dt><dd>{units(receipt.amounts.networkFeeLamports)}</dd></div></dl>:<p>RPC status only. Signature ownership and network fee are unverified.</p>}<code style={{overflowWrap:'anywhere'}}>{receipt.signature}</code></section>:null}
 </>:null}
 </section>;
}
