// Research capture only. It is never a consensus observation or settlement oracle.
export class ResearchCaptureCore {
  constructor({
    source = "Coinbase Exchange BTC-USD imported capture",
    method = "wen-research/1",
    requireHeartbeat = true,
    dropLate = false,
  } = {}) {
    this.source = source;
    this.method = method;
    this.requireHeartbeat = requireHeartbeat;
    this.dropLate = dropLate;
    this.late = [];
    this.events = [];
    this.lastByType = { ticker: -1n, heartbeat: -1n };
    this.generation = 0;
    this.connected = false;
    this.fault = null;
    this.gaps = [];
    this.gapStart = null;
  }
  connect(at) {
    if (at && this.gapStart === null)
      this.gapStart = Math.floor(Date.parse(at) / 60000) * 60000;
    this.connected = true;
    this.fault = null;
    this.generation++;
  }
  disconnect(at) {
    if (at && this.gapStart === null) this.gapStart = Date.parse(at);
    this.connected = false;
  }
  ingest(e) {
    if (!this.connected) throw Error("capture disconnected");
    if (
      !e ||
      !["ticker", "heartbeat"].includes(e.type) ||
      e.product_id !== "BTC-USD" ||
      !/^\d+$/.test(String(e.sequence)) ||
      !Number.isFinite(Date.parse(e.time)) ||
      !Number.isFinite(Date.parse(e.receivedAt))
    )
      throw Error("invalid capture event");
    const seq = BigInt(e.sequence);
    if (seq <= this.lastByType[e.type]) return false;
    if (
      e.type === "ticker" &&
      (!Number.isFinite(Number(e.best_bid)) ||
        !Number.isFinite(Number(e.best_ask)) ||
        Number(e.best_bid) <= 0 ||
        Number(e.best_ask) < Number(e.best_bid))
    )
      throw Error("invalid bid/ask");
    const old = this.events.at(-1);
    if (
      old &&
      old.generation === this.generation &&
      Date.parse(e.time) < Date.parse(old.time)
    ) {
      if (this.dropLate) {
        this.late.push({
          at: Date.parse(e.receivedAt),
          id: `${this.generation}:ticker:${e.sequence}`,
        });
        this.late = this.late.filter(
          (x) => x.at >= Date.parse(e.receivedAt) - 180000,
        );
        return false;
      }
      this.fault = "out-of-order exchange time";
      return false;
    }
    if (e.type === "ticker" && this.gapStart !== null) {
      const end = Date.parse(e.receivedAt);
      if (end > this.gapStart) this.gaps.push([this.gapStart, end]);
      this.gapStart = null;
    }
    this.lastByType[e.type] = seq;
    this.events.push({
      ...e,
      sequence: String(seq),
      generation: this.generation,
    });
    const cutoff = Date.parse(e.receivedAt) - 48 * 60 * 60 * 1000;
    this.events = this.events.filter((x) => Date.parse(x.receivedAt) >= cutoff);
    if (this.events.length > 200000) {
      this.fault = "capture capacity exceeded";
      this.events.shift();
    }
    return true;
  }
  snapshot(now) {
    const end = Date.parse(now);
    if (!Number.isFinite(end)) throw Error("invalid evaluation time");
    const eligible = this.events.filter(
      (e) => Date.parse(e.time) <= end && Date.parse(e.receivedAt) <= end,
    );
    const tick = eligible.filter((e) => e.type === "ticker").at(-1),
      last = eligible.filter((e) => e.type === "heartbeat").at(-1);
    const fresh =
      this.connected &&
      !this.fault &&
      tick &&
      (!this.requireHeartbeat || last) &&
      tick.generation === this.generation &&
      (!this.requireHeartbeat || last.generation === this.generation) &&
      end - Date.parse(tick.receivedAt) <= 5000 &&
      end - Date.parse(tick.time) <= 5000 &&
      (!this.requireHeartbeat ||
        (end - Date.parse(last.receivedAt) <= 5000 &&
          end - Date.parse(last.time) <= 5000));
    const map = new Map();
    for (const e of eligible.filter((e) => e.type === "ticker")) {
      const minute = Math.floor(Date.parse(e.time) / 60000) * 60000;
      if (minute + 60000 > end) continue;
      const gaps =
        this.gapStart === null
          ? this.gaps
          : [...this.gaps, [this.gapStart, end]];
      if (gaps.some(([a, b]) => minute < b && minute + 60000 > a)) continue;
      map.set(minute, {
        at: new Date(minute + 60000).toISOString(),
        midpoint: (Number(e.best_bid) + Number(e.best_ask)) / 2,
        sourceIds: [`${e.generation}:ticker:${e.sequence}`],
      });
    }
    const candles = [...map.values()];
    return {
      source: this.source,
      method: this.method,
      at: now,
      quality: fresh ? "valid" : this.fault ? "invalid" : "stale",
      quote: fresh ? (Number(tick.best_bid) + Number(tick.best_ask)) / 2 : null,
      candles,
      observationIds: eligible.map(
        (e) => `${e.generation}:${e.type}:${e.sequence}`,
      ),
      authoritative: false,
      ignoredLateObservations: this.late.filter(
        (x) => x.at <= end && x.at >= end - 180000,
      ).length,
    };
  }
  metrics(now, lookbackMinutes, archived = []) {
    if (![1, 30, 60, 240, 720, 1440].includes(lookbackMinutes))
      throw Error("unsupported lookback");
    const s = this.snapshot(now),
      end = Math.floor(Date.parse(now) / 60000) * 60000;
    if (archived.length) {
      const combined = new Map(archived.map((c) => [c.at, c]));
      for (const c of s.candles) combined.set(c.at, c);
      const gaps =
        this.gapStart === null
          ? this.gaps
          : [...this.gaps, [this.gapStart, Date.parse(now)]];
      s.candles = [...combined.values()]
        .filter(
          (c) =>
            !gaps.some(
              ([a, b]) => Date.parse(c.at) - 60000 < b && Date.parse(c.at) > a,
            ),
        )
        .sort((a, b) => Date.parse(a.at) - Date.parse(b.at));
    }
    const closes = Array.from({ length: lookbackMinutes + 1 }, (_, i) =>
      s.candles.find(
        (c) => Date.parse(c.at) === end - (lookbackMinutes - i) * 60000,
      ),
    );
    if (
      s.quality !== "valid" ||
      closes.some((c) => !c) ||
      Date.parse(now) - end > 90000
    )
      return {
        ...s,
        metrics: null,
        reason:
          s.quality !== "valid"
            ? "Fresh quote unavailable"
            : "Incomplete minute history",
      };
    const prices = closes.map((c) => c.midpoint);
    const round = (x) => Math.sign(x) * Math.floor(Math.abs(x) + 0.5);
    return {
      ...s,
      metrics: {
        returnBps: String(round(10000 * (prices.at(-1) / prices[0] - 1))),
        realizedVolatilityBps: String(
          round(
            10000 *
              Math.sqrt(
                prices
                  .slice(1)
                  .reduce((sum, p, i) => sum + Math.log(p / prices[i]) ** 2, 0),
              ),
          ),
        ),
      },
      lookbackMinutes,
    };
  }
}
