import React, { useRef, useState } from "react";
import {
  CAPTURE_MAX_BYTES,
  inspectCapture,
  captureExport,
  type CaptureResult,
} from "./capture.js";
function download(name: string, text: string) {
  const url = URL.createObjectURL(
    new Blob([text], { type: "application/json" }),
  );
  const a = document.createElement("a");
  a.href = url;
  a.download = name;
  a.click();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}
export function CaptureResearch() {
  const [raw, setRaw] = useState(""),
    [result, setResult] = useState<CaptureResult | null>(null),
    [error, setError] = useState(""),
    [busy, setBusy] = useState(false);
  const request = useRef(0);
  async function inspect(horizon?: number) {
    const id = ++request.current;
    setBusy(true);
    setError("");
    setResult(null);
    try {
      const r = await inspectCapture(raw, horizon);
      if (id === request.current) setResult(r);
    } catch (e) {
      if (id === request.current) setError((e as Error).message);
    } finally {
      if (id === request.current) setBusy(false);
    }
  }
  function edit(value: string) {
    request.current++;
    setBusy(false);
    setRaw(value);
    setResult(null);
    setError("");
  }
  const candles = result?.summary.candles ?? [];
  const values = candles.map((c) => c.midpoint),
    low = Math.min(...values),
    high = Math.max(...values),
    span = high - low || 1;
  const first = Date.parse(candles[0]?.at ?? ""),
    timeSpan = Date.parse(candles.at(-1)?.at ?? "") - first || 1;
  return (
    <div className="wr-panel" aria-label="Captured BTC research">
      <h3>Historical capture</h3>
      <label>
        BTC capture NDJSON
        <textarea
          aria-label="BTC capture NDJSON"
          value={raw}
          onChange={(e) => edit(e.target.value)}
          spellCheck={false}
        />
      </label>
      <label>
        Import BTC capture
        <input
          type="file"
          accept=".ndjson,.jsonl,application/x-ndjson"
          onChange={async (e) => {
            const f = e.target.files?.[0];
            if (!f) return;
            const id = ++request.current;
            setResult(null);
            if (f.size > CAPTURE_MAX_BYTES) {
              setError("Capture exceeds 2 MiB");
              return;
            }
            const text = await f.text();
            if (id === request.current) edit(text);
          }}
        />
      </label>
      <button disabled={!raw || busy} onClick={() => void inspect()}>
        Inspect capture
      </button>
      <details>
        <summary>Capture format</summary>
        <p>
          NDJSON: one wen-research-capture/1 header (source, evaluatedAt,
          lookbackMinutes), then connect/disconnect records and Coinbase BTC-USD
          ticker/heartbeat records. Sequence and bid/ask values are exact
          strings. See the package capture contract. This tab is transient;
          export the original to retain it. Kraken imports use
          wen-kraken-capture/1 with original raw WebSocket messages and receive
          times.
        </p>
      </details>
      {error && <p role="alert">{error}</p>}
      {result && (
        <>
          <p className="wt-badge">
            Historical · unverified · execution disabled
          </p>
          <dl>
            <dt>Source / evaluated at</dt>
            <dd>
              {result.source} · {result.evaluatedAt}
            </dd>
            <dt>Feed / method</dt>
            <dd>
              {result.summary.source} · {result.summary.method}
            </dd>
            <dt>Capture SHA-256</dt>
            <dd>
              <code>{result.captureSHA256}</code>
            </dd>
            <dt>Quality at recorded time</dt>
            <dd>{result.summary.quality}</dd>
            <dt>Lookback</dt>
            <dd>{result.lookbackMinutes} minutes</dd>
            <dt>Return / realized volatility</dt>
            <dd>
              {result.summary.metrics
                ? `${result.summary.metrics.returnBps} bps / ${result.summary.metrics.realizedVolatilityBps} bps`
                : `Unavailable · ${result.summary.reason}`}
            </dd>
            <dt>Missing minute closes</dt>
            <dd>{result.missingMinuteCloses.length}</dd>
          </dl>
          <nav aria-label="Capture lookback">
            {[1, 30, 60, 240, 720, 1440].map((n) => (
              <button
                key={n}
                aria-pressed={result.lookbackMinutes === n}
                onClick={() => void inspect(n)}
              >
                {n}m
              </button>
            ))}
          </nav>
          {candles.length > 0 && (
            <svg
              viewBox="0 0 700 200"
              role="img"
              aria-label="Historical BTC midpoint closes"
              style={{ width: "100%", height: "200px", background: "#15141c" }}
            >
              <title>
                Recorded completed-minute midpoint closes; gaps are not
                connected
              </title>
              {candles.map((c, i) => {
                const x = 20 + ((Date.parse(c.at) - first) / timeSpan) * 660,
                  y = 170 - ((c.midpoint - low) / span) * 140;
                return (
                  <circle key={c.at} cx={x} cy={y} r="3" fill="#27C5DA">
                    <title>
                      {c.at}: {c.midpoint} USD
                    </title>
                  </circle>
                );
              })}
              <text x="20" y="15" fill="#B7B2C8">
                {high.toFixed(2)} USD
              </text>
              <text x="20" y="195" fill="#B7B2C8">
                {low.toFixed(2)} USD
              </text>
            </svg>
          )}
          <button onClick={() => download("btc-capture.ndjson", result.raw)}>
            Export original capture
          </button>
          <button
            onClick={() =>
              download("btc-research-snapshot.json", captureExport(result))
            }
          >
            Export research snapshot
          </button>
          <details>
            <summary>Observation provenance and gaps</summary>
            <p>
              {result.eventCount} imported records · {result.summary.method}
            </p>
            <p>
              {result.missingMinuteCloses.join(", ") ||
                "No missing closes in selected lookback"}
            </p>
            <div className="wr-table">
              <table>
                <thead>
                  <tr>
                    <th>Minute close UTC</th>
                    <th>BTC midpoint USD</th>
                    <th>Observation</th>
                  </tr>
                </thead>
                <tbody>
                  {candles.map((c) => (
                    <tr key={c.at}>
                      <td>{c.at}</td>
                      <td>{c.midpoint}</td>
                      <td>{c.sourceIds.join(", ")}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </details>
        </>
      )}
    </div>
  );
}
