import { uint } from './scalars.js';
export function validateWeights(weights: readonly number[]): void {
  if(!Array.isArray(weights)||weights.length!==5||weights.some(w=>!Number.isInteger(w)||w<0||w>10000)||weights.reduce((a,b)=>a+b,0)!==10000) throw Error('five weights must total 10000');
}
export function compileAllocation(amount: string, weights: readonly number[]): string[] {
  const n=uint(amount); if(n===0n) throw Error('positive amount required'); validateWeights(weights);
  const parts=weights.map(w=>n*BigInt(w)/10000n);
  const order=weights.map((w,i)=>({i,remainder:n*BigInt(w)%10000n})).sort((a,b)=>a.remainder===b.remainder?a.i-b.i:a.remainder>b.remainder?-1:1);
  const left=Number(n-parts.reduce((a,b)=>a+b,0n)); for(let j=0;j<left;j++) parts[order[j].i]++;
  if(parts.some((p,i)=>(weights[i]>0&&p===0n)||(p>0n&&p<10000000n))) throw Error('nonzero allocation below entry minimum');
  return parts.map(String);
}
