import type {Schedule} from './strategy.js';
import {validateSchedule} from './validation.js';
import {uint,timestamp,sha256} from './scalars.js';
export interface Slot {roundId:string; opensAt:string}
export interface ScheduleState {acceptedRounds:number;acceptedRoundsToday:number;lastAcceptedRound:string|null}
function baseEligible(s:Schedule,slot:Slot):boolean {
  const id=uint(slot.roundId),open=timestamp(slot.opensAt),anchor=uint(s.anchorRound);
  if(open<timestamp(s.startsAt)||open>=timestamp(s.expiresAt)||id<anchor||(id-anchor)%BigInt(s.everyNthRound)!==0n||s.skipRoundIds.includes(slot.roundId)||(s.selectedRoundIds.length>0&&!s.selectedRoundIds.includes(slot.roundId)))return false;
  const date=new Date(open),minute=date.getUTCHours()*60+date.getUTCMinutes();
  return !s.utcWindows.length||s.utcWindows.some(w=>minute>=w.startMinute&&minute<w.endMinute);
}
// Pure filtering over caller-supplied canonical slots, never a scheduler or oracle.
export function candidateSlots(s:Schedule,slots:Slot[]):Slot[] {
  validateSchedule(s);if(slots.length>144)throw Error('too many slots');const seen=new Set<string>();
  const out=slots.filter(slot=>{if(seen.has(slot.roundId))throw Error('duplicate slot');seen.add(slot.roundId);return baseEligible(s,slot);});
  return out.sort((a,b)=>uint(a.roundId)<uint(b.roundId)?-1:1);
}
export function validateSlotInventory(s:Schedule,slots:Slot[]):void {
 validateSchedule(s); if(!slots.length||slots.length>144)throw Error('incomplete slot inventory');
 const ordered=[...slots].sort((a,b)=>uint(a.roundId)<uint(b.roundId)?-1:1);
 const start=timestamp(s.startsAt),end=timestamp(s.expiresAt);
 for(let i=0;i<ordered.length;i++){
  const now=timestamp(ordered[i].opensAt);uint(ordered[i].roundId);
  if(now<start||now>=end)throw Error('inventory outside session');
  if(i===0&&now-start>=600000)throw Error('missing first slot');
  if(i>0&&(uint(ordered[i].roundId)!==uint(ordered[i-1].roundId)+1n||now-timestamp(ordered[i-1].opensAt)!==600000))throw Error('inventory gap');
 }
 if(timestamp(ordered.at(-1)!.opensAt)+600000<end)throw Error('missing last slot');
}
export async function pinRandom(s:Schedule,slots:Slot[]):Promise<string[]> {
  validateSlotInventory(s,slots);const candidates=candidateSlots(s,slots);if(!s.randomSelection)throw Error('random absent');
  if(candidates.length<s.randomSelection.count)throw Error('review reduced count');
  const seed=s.randomSelection.seedHex;
  const ranked=await Promise.all(candidates.map(async slot=>({id:slot.roundId,hash:await sha256(new TextEncoder().encode(seed+':'+slot.roundId))})));
  ranked.sort((a,b)=>a.hash===b.hash?(uint(a.id)<uint(b.id)?-1:1):a.hash<b.hash?-1:1);
  return ranked.slice(0,s.randomSelection.count).map(x=>x.id);
}
export function eligible(s:Schedule,slot:Slot,state:ScheduleState,pinnedIDs:string[]=[]):boolean {
  validateSchedule(s);if(!baseEligible(s,slot))return false;
  if(!Number.isSafeInteger(state.acceptedRounds)||!Number.isSafeInteger(state.acceptedRoundsToday)||state.acceptedRounds<0||state.acceptedRoundsToday<0||state.acceptedRoundsToday>state.acceptedRounds)throw Error('schedule state');
  if((state.acceptedRounds===0)!==(state.lastAcceptedRound===null))throw Error('inconsistent accepted history');
  if(state.acceptedRounds>=s.maxRoundsTotal||state.acceptedRoundsToday>=s.maxRoundsPerUtcDay)return false;
  if(s.randomSelection){if(pinnedIDs.length!==s.randomSelection.count||new Set(pinnedIDs).size!==pinnedIDs.length)throw Error('pinned selection');pinnedIDs.forEach(uint);if(!pinnedIDs.includes(slot.roundId))return false;}
  if(state.lastAcceptedRound!==null){const id=uint(slot.roundId),last=uint(state.lastAcceptedRound);if(id<=last||id-last<=BigInt(s.cooldownRounds))return false;}
  return true;
}
