// Read-only selection lifecycle: no cached receipt is transferable to another wallet/round.
/** @param {any} provider @param {{now?:()=>number,onChange?:(state:any)=>void}} options */
export function createDeploymentReadSession(provider,{now=Date.now,onChange=()=>{}}={}){
 let generation=0,controller=null,selection=null,disposed=false,state={status:'idle',snapshot:null,receipt:null,error:null};
 const scopeKey=(identity,input)=>JSON.stringify({identity,wallet:input.wallet,roundSlot:input.roundSlot});
 const finalized=new Map();
 const floors=new Map(),key=x=>JSON.stringify(x),publish=x=>{state=x;if(!disposed)onChange(x)};
 const cancel=()=>{generation++;controller?.abort();controller=null};
 const expiry=()=>state.snapshot&&now()>=state.snapshot.expiresAtMs;
 const inspect=async(input,family=null)=>{
   const treasury=family==='treasury',operating=family==='operating',protocol=treasury||operating;
   if(!selection||state.status!=='ready'||expiry()||(!protocol&&input.wallet!==selection.wallet)||input.roundSlot!==selection.roundSlot)throw Error('Refresh this wallet and round before inspecting a receipt.');
   if(treasury){if(!selection.includeTreasury||typeof provider.treasuryReceipt!=='function')throw Error('Refresh treasury scope before inspecting protocol execution.');}
   else if(operating){if(!selection.includeOperating||typeof provider.operatingReceipt!=='function')throw Error('Refresh Operating scope before inspecting collection.');}
   else{
   if(['ClaimBtc','RecoverSol'].includes(input.operation)&&!selection.includeBtc)throw Error('Refresh BTC conversion scope before inspecting a payout receipt.');
   if(['StakingClaimBtc','StakingRecoverSol'].includes(input.operation)&&!selection.includeStaking)throw Error('Refresh staking scope before inspecting a beneficiary receipt.');
   if(['CarryClaimBtc','CarryRefundBtc','CarryRefundSol'].includes(input.operation)&&!selection.includeCarry)throw Error('Refresh carry scope before inspecting a release or refund receipt.');
   if(['DailyPrizeBtc','DailyPrizeSol','DailyRefundBtc','DailyRefundSol'].includes(input.operation)&&!selection.includeDaily)throw Error('Refresh daily scope before inspecting a prize or contributor receipt.');
   }
   const expected=key(selection),ticket=generation,snapshot=state.snapshot;controller=new AbortController();publish({...state,status:'checking',receipt:null,treasuryReceipt:null,operatingReceipt:null,error:null});
   try{const receipt=await (protocol?provider[family+'Receipt'](input,controller.signal):provider.receipt(input,controller.signal));if(disposed||ticket!==generation||key(selection)!==expected)return;
    if(now()>=snapshot.expiresAtMs||now()>=receipt.expiresAtMs)throw Error('Receipt context expired.');
    const scope=scopeKey(snapshot.identity,selection),floor=floors.get(scope)??0n;
    if(receipt.currentAccountSlot!==undefined){const current=BigInt(receipt.currentAccountSlot);if(current<floor)throw Error('Receipt account slot regressed.');floors.set(scope,current)}
    const receiptKey=key({scope,family,signature:input.signature,operation:input.operation,...(treasury?{day:input.day,hour:input.hour,attempt:input.attempt,side:input.side,nonce:input.nonce}:{entry:input.entry})}),prior=finalized.get(receiptKey);
    const proof=key({status:receipt.status,message:receipt.messageSha256,...(protocol?{effects:receipt.effects,disposition:receipt.disposition,payer:receipt.payer,fee:receipt.networkFeeLamports}:{amounts:receipt.amounts})});
    if(prior&&prior!==proof)throw Error('Finalized receipt changed or became unavailable. Refresh and reconcile.');
    if(['finalized-success','finalized-failed','finalized-no-payment'].includes(receipt.status))finalized.set(receiptKey,proof);
    publish({status:'ready',snapshot,receipt:protocol?null:receipt,treasuryReceipt:treasury?receipt:null,operatingReceipt:operating?receipt:null,error:null});
   }catch(e){if(!disposed&&ticket===generation)publish({status:'error',snapshot:null,receipt:null,error:String(e?.message??e)})}
 };
 return {
  getState(){if(expiry()){cancel();publish({status:'expired',snapshot:null,receipt:null,error:'Read expired. Refresh before inspecting a receipt.'})}else if((state.operatingReceipt??state.treasuryReceipt??state.receipt)&&now()>=(state.operatingReceipt??state.treasuryReceipt??state.receipt).expiresAtMs){cancel();publish({...state,status:'ready',receipt:null,treasuryReceipt:null,operatingReceipt:null,error:'Transaction status expired. Inspect again.'})}return state},
  invalidate(){cancel();selection=null;publish({status:'idle',snapshot:null,receipt:null,error:null})},
  clearReceipt(){cancel();publish({status:state.snapshot&&!expiry()?'ready':'idle',snapshot:state.snapshot&&!expiry()?state.snapshot:null,receipt:null,treasuryReceipt:null,operatingReceipt:null,error:null})},
  async read(input){cancel();selection=structuredClone(input);const expected=key(selection),ticket=generation;controller=new AbortController();publish({status:'loading',snapshot:null,receipt:null,error:null});
   try{const snapshot=await provider.read(input,controller.signal);if(disposed||ticket!==generation||key(selection)!==expected)return;
    if(now()>=snapshot.expiresAtMs)throw Error('Read expired.');
    const scope=scopeKey(snapshot.identity,input),floor=floors.get(scope)??0n;
    if(BigInt(snapshot.slot)<floor)throw Error('Out-of-order finalized read.');
    floors.set(scope,BigInt(snapshot.slot));publish({status:'ready',snapshot,receipt:null,error:null});
   }catch(e){if(!disposed&&ticket===generation)publish({status:'error',snapshot:null,receipt:null,error:String(e?.message??e)})}
  },
  inspect(input){return inspect(input)},
  inspectTreasury(input){return inspect(input,'treasury')},
  inspectOperating(input){return inspect(input,'operating')},
  dispose(){cancel();disposed=true;selection=null;state={status:'idle',snapshot:null,receipt:null,error:null}}
 }
}

// A page is a set of separate current round snapshots, never an atomic wallet balance.
/** @param {any} provider @param {{now?:()=>number,onChange?:(state:any)=>void}} options */
export function createDeploymentHistorySession(provider,{now=Date.now,onChange=()=>{}}={}){
 let state={status:'idle',page:null,error:null},generation=0,controller=null,disposed=false;
 const floors=new Map();
 const publish=v=>{state=v;if(!disposed)onChange(v)};
 const cancel=()=>{generation++;controller?.abort();controller=null};
 return {
  getState(){if(state.page&&now()>=state.page.expiresAtMs){cancel();publish({status:'expired',page:null,error:'History expired. Refresh the index.'})}return state},
  invalidate(){cancel();publish({status:'idle',page:null,error:null})},
  async load(input){cancel();const ticket=generation;controller=new AbortController();publish({status:'loading',page:null,error:null});
   try{const page=await provider.history(structuredClone(input),controller.signal);if(disposed||ticket!==generation)return;
    if(now()>=page.expiresAtMs)throw Error('History expired.');
    const updates=[];
    for(const item of page.items){if(item.status!=='verified')continue;const snapshot=item.snapshot,key=JSON.stringify({identity:page.identity,wallet:input.wallet,roundSlot:item.roundSlot}),slot=BigInt(snapshot.slot);
     if(now()>=snapshot.expiresAtMs||slot<(floors.get(key)??0n))throw Error('History round expired or finalized slot regressed.');updates.push([key,slot]);}
    for(const [key,slot] of updates)floors.set(key,slot);
    publish({status:'ready',page,error:null});
   }catch(e){if(!disposed&&ticket===generation)publish({status:'error',page:null,error:String(e?.message??e)})}
  },
  dispose(){cancel();disposed=true;state={status:'idle',page:null,error:null}}
 };
}
