import {
  strictJSON,
  validateStrategy,
} from "../../strategy-contract/src/index.js";
import type { Strategy } from "../../strategy-contract/src/index.js";
export type Scope = {
  market: string;
  terms: string;
  evidence: "paper" | "historical-replay" | "actual";
  from: string;
  to: string;
  dataset: string;
  valuation: string;
  costs: string;
  coverage: string;
};
export type HistoryRow = {
  id: string;
  cursor: number;
  strategyDigest: string;
  at: string;
  finality: "provisional" | "finalized" | "reverted";
  category: "mining" | "staking" | "prize" | "carry" | "transfer";
  committed: string;
  returned: string;
  fees: string;
  forfeitures: string;
  userCosts: string;
  btcSaleSOL: string;
  satSaleSOL: string;
  btcPending: string;
  btcReceived: string;
  satEarned: string;
  satClaimed: string;
  satSold: string;
};
export type Bundle = {
  schema: "wen-history-import/1";
  source: string;
  verified: false;
  scope: Scope;
  initialBankroll: string | null;
  skipped: number | null;
  pendingExposure: string | null;
  rows: HistoryRow[];
  gaps: string[];
};
export type Version = {
  digest: string;
  raw: string;
  name: string;
  createdAt: string;
  origin: string;
};
export type Library = {
  revision: number;
  versions: Version[];
  bundles: Bundle[];
};
export type SavedChatSelection = {
  libraryRevision: number;
  strategyDigest?: string;
  bundleIndex?: number;
};
export interface ResearchStorage {
  label: string;
  load: () => Promise<Library>;
  save: (revision: number, raw: string) => Promise<Library>;
  importHistory: (revision: number, raw: string) => Promise<Library>;
}
const uint = /^(0|[1-9][0-9]*)$/;
const hex = /^[a-f0-9]{64}$/;
const amountKeys = [
  "committed",
  "returned",
  "fees",
  "forfeitures",
  "userCosts",
  "btcSaleSOL",
  "satSaleSOL",
  "btcPending",
  "btcReceived",
  "satEarned",
  "satClaimed",
  "satSold",
] as const;
function keys(v: any, required: string[], optional: string[] = []) {
  if (
    !v ||
    typeof v !== "object" ||
    Array.isArray(v) ||
    required.some((k) => !(k in v)) ||
    Object.keys(v).some((k) => ![...required, ...optional].includes(k))
  )
    throw Error("Unsupported record fields");
}
function text(v: unknown, max = 256) {
  if (typeof v !== "string" || !v.length || v.length > max)
    throw Error("Invalid text");
}
function amount(v: unknown) {
  if (typeof v !== "string" || !uint.test(v) || v.length > 30)
    throw Error("Invalid integer amount");
}
function date(v: unknown) {
  if (
    typeof v !== "string" ||
    !/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\dZ$/.test(v) ||
    !Number.isFinite(Date.parse(v)) ||
    new Date(v).toISOString().replace(".000Z", "Z") !== v
  )
    throw Error("Invalid UTC time");
}
export async function digest(raw: string) {
  return [
    ...new Uint8Array(
      await crypto.subtle.digest("SHA-256", new TextEncoder().encode(raw)),
    ),
  ]
    .map((x) => x.toString(16).padStart(2, "0"))
    .join("");
}
export function acceptStrategy(raw: string): Strategy {
  const s = strictJSON(new TextEncoder().encode(raw)) as Strategy;
  validateStrategy(s);
  if (s.execution.mandateId !== null || s.execution.mode !== "review")
    throw Error(
      "Import requires review mode and no mandate. Export an inert strategy first.",
    );
  return s;
}
export function cloneStrategy(raw: string, name: string): string {
  const s = strictJSON(new TextEncoder().encode(raw)) as Strategy;
  text(name, 80);
  s.name = name;
  s.execution = { mode: "review", runner: "browser", mandateId: null };
  const out = JSON.stringify(s, null, 2);
  acceptStrategy(out);
  return out;
}
export function parseBundle(raw: string): Bundle {
  if (new TextEncoder().encode(raw).length > 65536)
    throw Error("History import exceeds 64 KiB");
  const b = strictJSON(new TextEncoder().encode(raw)) as any;
  keys(b, [
    "schema",
    "source",
    "verified",
    "scope",
    "initialBankroll",
    "skipped",
    "pendingExposure",
    "rows",
    "gaps",
  ]);
  if (b.schema !== "wen-history-import/1" || b.verified !== false)
    throw Error("Imported history must be unverified");
  text(b.source);
  keys(b.scope, [
    "market",
    "terms",
    "evidence",
    "from",
    "to",
    "dataset",
    "valuation",
    "costs",
    "coverage",
  ]);
  for (const k of [
    "market",
    "terms",
    "dataset",
    "valuation",
    "costs",
    "coverage",
  ])
    text(b.scope[k]);
  if (!["actual", "paper", "historical-replay"].includes(b.scope.evidence))
    throw Error("Invalid evidence class");
  date(b.scope.from);
  date(b.scope.to);
  if (b.scope.from >= b.scope.to) throw Error("Invalid period");
  for (const k of ["initialBankroll", "pendingExposure"])
    if (b[k] !== null) amount(b[k]);
  if (b.skipped !== null && (!Number.isSafeInteger(b.skipped) || b.skipped < 0))
    throw Error("Invalid skip count");
  if (
    !Array.isArray(b.rows) ||
    b.rows.length > 1000 ||
    !Array.isArray(b.gaps) ||
    b.gaps.length > 1000
  )
    throw Error("Record capacity exceeded");
  b.gaps.forEach((x: any) => text(x));
  for (const r of b.rows) {
    keys(r, [
      "id",
      "cursor",
      "strategyDigest",
      "at",
      "finality",
      "category",
      ...amountKeys,
    ]);
    text(r.id);
    if (
      !Number.isSafeInteger(r.cursor) ||
      r.cursor < 1 ||
      !hex.test(r.strategyDigest)
    )
      throw Error("Invalid record identity");
    date(r.at);
    if (r.at < b.scope.from || r.at >= b.scope.to)
      throw Error("History lies outside declared period");
    if (
      !["provisional", "finalized", "reverted"].includes(r.finality) ||
      !["mining", "staking", "prize", "carry", "transfer"].includes(r.category)
    )
      throw Error("Invalid history state");
    amountKeys.forEach((k) => amount(r[k]));
  }
  // Identity and cursor bind corrections. Conflicting duplicates must not silently replace records.
  reconcile(b.rows);
  return b;
}
export function reconcile(rows: HistoryRow[]): HistoryRow[] {
  const m = new Map<string, HistoryRow>();
  for (const r of [...rows].sort((a, b) => a.cursor - b.cursor)) {
    const old = m.get(r.id);
    if (
      old &&
      old.cursor === r.cursor &&
      JSON.stringify(old) !== JSON.stringify(r)
    )
      throw Error("Conflicting history event");
    if (!old || r.cursor > old.cursor) m.set(r.id, r);
  }
  return [...m.values()].sort(
    (a, b) => a.at.localeCompare(b.at) || a.id.localeCompare(b.id),
  );
}
export function summarize(b: Bundle, strategyDigest: string) {
  let committed = 0n,
    returned = 0n,
    fees = 0n,
    forfeitures = 0n,
    costs = 0n,
    btcSales = 0n,
    satSales = 0n,
    btc = 0n,
    pending = 0n,
    sat = 0n,
    claimed = 0n,
    sold = 0n,
    cumulative = 0n,
    peak = 0n,
    drawdown = 0n;
  let entries = 0,
    unsettled = 0;
  const overlays: Record<string, string> = {};
  for (const r of reconcile(b.rows).filter(
    (r) => r.strategyDigest === strategyDigest,
  )) {
    if (r.finality === "reverted") continue;
    if (r.finality !== "finalized") {
      unsettled++;
      continue;
    }
    if (r.category !== "mining") {
      overlays[r.category] = String(
        BigInt(overlays[r.category] ?? "0") + BigInt(r.returned),
      );
      continue;
    }
    entries++;
    committed += BigInt(r.committed);
    returned += BigInt(r.returned);
    fees += BigInt(r.fees);
    forfeitures += BigInt(r.forfeitures);
    costs += BigInt(r.userCosts);
    btcSales += BigInt(r.btcSaleSOL);
    satSales += BigInt(r.satSaleSOL);
    btc += BigInt(r.btcReceived);
    pending += BigInt(r.btcPending);
    sat += BigInt(r.satEarned);
    claimed += BigInt(r.satClaimed);
    sold += BigInt(r.satSold);
    cumulative +=
      BigInt(r.returned) -
      BigInt(r.committed) -
      BigInt(r.userCosts) +
      BigInt(r.btcSaleSOL) +
      BigInt(r.satSaleSOL);
    if (cumulative > peak) peak = cumulative;
    if (peak - cumulative > drawdown) drawdown = peak - cumulative;
  }
  return {
    entries,
    unsettled,
    committed: String(committed),
    returned: String(returned),
    fees: String(fees),
    forfeitures: String(forfeitures),
    userCosts: String(costs),
    btcReceived: String(btc),
    btcPending: String(pending),
    satEarned: String(sat),
    satClaimed: String(claimed),
    satSold: String(sold),
    btcSaleSOL: String(btcSales),
    satSaleSOL: String(satSales),
    netSOL: String(cumulative),
    drawdown: String(drawdown),
    costPerSAT:
      claimed === 0n
        ? null
        : {
            numerator: String(fees + forfeitures + costs - btcSales),
            denominator: String(claimed),
          },
    perTurnover:
      committed === 0n
        ? null
        : { numerator: String(cumulative), denominator: String(committed) },
    overlays,
  };
}
export function compareScope(bundles: Bundle[]) {
  if (bundles.length < 2 || bundles.length > 4)
    throw Error("Choose 2–4 strategies");
  const fields = Object.keys(bundles[0].scope) as (keyof Scope)[];
  const differences = fields.filter((k) =>
    bundles.some((b) => b.scope[k] !== bundles[0].scope[k]),
  );
  return {
    differences,
    rankable: false,
    reason: differences.length
      ? "Different comparison scopes"
      : bundles.some((b) => b.gaps.length)
        ? "Incomplete observation coverage"
        : "Imported evidence is unverified; descriptive comparison only",
  };
}
export function decimal(raw: string, precision = 9) {
  const n = BigInt(raw),
    sign = n < 0n ? "-" : "",
    abs = n < 0n ? -n : n;
  return (
    sign +
    (abs / 10n ** BigInt(precision)).toString() +
    (
      "." + (abs % 10n ** BigInt(precision)).toString().padStart(precision, "0")
    ).replace(/\.?0+$/, "")
  );
}
export function browserStorage(namespace: string): ResearchStorage {
  const key = "wen-research-v1:" + namespace;
  const load = async () => {
    const raw = localStorage.getItem(key);
    if (!raw) return { revision: 0, versions: [], bundles: [] };
    const d = JSON.parse(raw) as Library;
    if (
      !Number.isSafeInteger(d.revision) ||
      !Array.isArray(d.versions) ||
      !Array.isArray(d.bundles)
    )
      throw Error("Invalid local library; export and preserve storage");
    for (const v of d.versions) {
      acceptStrategy(v.raw);
      if ((await digest(v.raw)) !== v.digest)
        throw Error("Library digest mismatch");
    }
    d.bundles.forEach((b) => parseBundle(JSON.stringify(b)));
    return d;
  };
  const mutate = async (
    revision: number,
    change: (d: Library) => Promise<boolean | void>,
  ) => {
    if (!navigator.locks)
      throw Error("Safe browser storage locking unavailable");
    return navigator.locks.request(key, async () => {
      const d = await load();
      if (d.revision !== revision)
        throw Error("Library changed; reload before saving");
      if ((await change(d)) === false) return d;
      d.revision++;
      const raw = JSON.stringify(d);
      if (raw.length > 2000000)
        throw Error("Local library capacity reached; export records");
      localStorage.setItem(key, raw);
      return d;
    });
  };
  return {
    label: "Private browser storage · export a backup",
    load,
    save: (rev, raw) =>
      mutate(rev, async (d) => {
        const s = acceptStrategy(raw),
          id = await digest(raw);
        if (d.versions.some((v) => v.digest === id)) return false;
        if (d.versions.length >= 100)
          throw Error("100-version capacity reached");
        d.versions.push({
          digest: id,
          raw,
          name: s.name,
          createdAt: new Date().toISOString(),
          origin: "owner-import",
        });
      }),
    importHistory: (rev, raw) =>
      mutate(rev, async (d) => {
        const b = parseBundle(raw);
        if (d.bundles.length >= 50) throw Error("50-bundle capacity reached");
        d.bundles.push(b);
      }),
  };
}
