// One wire decoder for capture import and the recorder; parser supplied by F1.
export function decodeKrakenWire(raw, parse) {
  if (typeof raw !== "string" || new TextEncoder().encode(raw).length > 65536)
    throw Error("Kraken frame too large");
  return parse(
    raw.replace(
      /"(?:[^"\\]|\\.)*"|-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?/g,
      (t) => (t.startsWith('"') ? t : JSON.stringify(t)),
    ),
  );
}
export function decodeKraken(raw, parse) {
  const message = decodeKrakenWire(raw, parse);
  if (
    message.channel === "heartbeat" ||
    message.channel === "status" ||
    message.method === "subscribe"
  ) {
    if (
      message.success === false ||
      (message.channel === "status" && message.data?.[0]?.system !== "online")
    )
      throw Error("Kraken unavailable or subscription refused");
    return null;
  }
  if (
    message.channel !== "ticker" ||
    !["snapshot", "update"].includes(message.type) ||
    !Array.isArray(message.data) ||
    message.data.length !== 1
  )
    throw Error("Unsupported Kraken message");
  const d = message.data[0];
  if (
    d.symbol !== "BTC/USD" ||
    ![d.bid, d.ask].every(
      (v) =>
        typeof v === "string" &&
        /^\d{1,9}(\.\d{1,6})?$/.test(v) &&
        Number(v) > 0,
    ) ||
    Number(d.ask) < Number(d.bid)
  )
    throw Error("Invalid Kraken instrument or BBO");
  if (
    typeof d.timestamp !== "string" ||
    !/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d(?:\.\d{1,6})?Z$/.test(d.timestamp) ||
    !Number.isFinite(Date.parse(d.timestamp)) ||
    new Date(d.timestamp).toISOString().slice(0, 19) !==
      d.timestamp.slice(0, 19)
  )
    throw Error("Invalid Kraken source time");
  return { time: d.timestamp, best_bid: d.bid, best_ask: d.ask };
}
