import React, { useEffect, useState } from "react";
export type ResearchReader = (lookback: number) => Promise<unknown>;
export type ResearchChatReview = {
  schema: "wen-research-chat-review/1";
  profileId: string;
  revision: number;
  expiresAt: number;
  text: string;
  source: string;
};
export function researchChatReview(value: unknown): ResearchChatReview | null {
  const r = value as ResearchChatReview;
  return r?.schema === "wen-research-chat-review/1" &&
    Object.keys(r).length === 6 &&
    Object.keys(r).every((key) =>
      [
        "schema",
        "profileId",
        "revision",
        "expiresAt",
        "text",
        "source",
      ].includes(key),
    ) &&
    typeof r.profileId === "string" &&
    r.profileId.length > 0 &&
    r.profileId.length <= 80 &&
    Number.isSafeInteger(r.revision) &&
    r.revision >= 0 &&
    Number.isSafeInteger(r.expiresAt) &&
    r.expiresAt * 1000 > Date.now() &&
    r.expiresAt * 1000 <= Date.now() + 120000 &&
    typeof r.text === "string" &&
    new TextEncoder().encode(r.text).length <= 4000 &&
    r.text.length > 0 &&
    typeof r.source === "string" &&
    /^wen-research-review-v1:[a-f0-9]{64}$/.test(r.source)
    ? r
    : null;
}
export async function fetchSharedResearch(lookback: number) {
  const r = await fetch(`/api/mining/v1/research?lookback=${lookback}`, {
    cache: "no-store",
    credentials: "omit",
    signal: AbortSignal.timeout(4000),
  });
  if (!r.ok) throw Error("Research service unavailable");
  const text = await r.text();
  if (text.length > 262144) throw Error("Research response too large");
  return JSON.parse(text);
}
export function validateResearch(value: any) {
  if (
    !value ||
    value.schema !== "wen-research-data/1" ||
    value.execution !== "disabled" ||
    value.finality !== "research" ||
    value.method !== "wen-kraken-research/1" ||
    typeof value.sourceCursor !== "string" ||
    !/^\d{1,20}$/.test(value.sourceCursor) ||
    !Number.isFinite(Date.parse(value.generatedAt)) ||
    Math.abs(Date.now() - Date.parse(value.generatedAt)) > 10000
  )
    throw Error("Unsupported or stale research snapshot");
  const d = value.data;
  if (
    !d ||
    d.method !== value.method ||
    d.authoritative !== false ||
    !["valid", "stale", "invalid"].includes(d.quality) ||
    !Array.isArray(d.candles) ||
    d.candles.length > 1441 ||
    !Array.isArray(d.observationIds) ||
    d.observationIds.length > 1442 ||
    !/^[a-f0-9]{64}$/.test(d.inputDigest) ||
    !d.candles.every(
      (c: any) =>
        Number.isFinite(Date.parse(c.at)) &&
        Number.isFinite(c.midpoint) &&
        c.midpoint > 0,
    ) ||
    !(d.quote === null || (Number.isFinite(d.quote) && d.quote > 0)) ||
    !(
      d.metrics === null ||
      (typeof d.metrics?.returnBps === "string" &&
        /^-?\d+$/.test(d.metrics.returnBps) &&
        typeof d.metrics.realizedVolatilityBps === "string" &&
        /^\d+$/.test(d.metrics.realizedVolatilityBps))
    )
  )
    throw Error("Invalid research data");
  if (
    d.quote !== null &&
    (!Number.isFinite(Date.parse(d.quoteEventAt)) ||
      !Number.isFinite(Date.parse(d.quoteReceivedAt)) ||
      Date.parse(d.quoteEventAt) > Date.now() + 1000 ||
      Date.parse(d.quoteReceivedAt) > Date.now() + 1000)
  )
    throw Error("Missing quote time");
  return value;
}
export function SharedResearch({
  read = fetchSharedResearch,
  onDiscuss,
}: {
  read?: ResearchReader;
  onDiscuss?: (review: ResearchChatReview) => void;
}) {
  const [enabled, setEnabled] = useState(false),
    [lookback, setLookback] = useState(1),
    [snapshot, setSnapshot] = useState<any>(null),
    [error, setError] = useState(""),
    [clock, setClock] = useState(Date.now());
  useEffect(() => {
    if (!enabled) return;
    let active = true,
      timeout: ReturnType<typeof setTimeout>;
    const poll = async () => {
      try {
        const v = validateResearch(await read(lookback));
        if (active) {
          setSnapshot(v);
          setError("");
        }
      } catch (e) {
        if (active) {
          setSnapshot(null);
          setError((e as Error).message);
        }
      } finally {
        if (active) timeout = setTimeout(poll, 5000);
      }
    };
    setSnapshot(null);
    void poll();
    return () => {
      active = false;
      clearTimeout(timeout);
    };
  }, [enabled, lookback, read]);
  useEffect(() => {
    if (!enabled) return;
    const t = setInterval(() => setClock(Date.now()), 500);
    return () => clearInterval(t);
  }, [enabled]);
  const d = snapshot?.data,
    fresh =
      d &&
      d.quality === "valid" &&
      clock - Date.parse(d.quoteEventAt) <= 5000 &&
      clock - Date.parse(d.quoteReceivedAt) <= 5000 &&
      clock - Date.parse(snapshot.generatedAt) <= 10000;
  const review = researchChatReview(snapshot?.chatContext);
  const candles = d?.candles ?? [],
    min = Math.min(...candles.map((c: any) => c.midpoint)),
    max = Math.max(...candles.map((c: any) => c.midpoint)),
    span = max - min || 1;
  return (
    <section className="wr-panel" aria-label="Shared Kraken research">
      <h3>Kraken BTC/USD</h3>
      <button
        onClick={() => {
          setEnabled((v) => !v);
          setSnapshot(null);
          setError("");
        }}
      >
        {enabled ? "Disconnect research" : "Connect research"}
      </button>
      {enabled && (
        <>
          <nav aria-label="Shared research lookback">
            {[1, 30, 60, 240, 720, 1440].map((n) => (
              <button
                key={n}
                aria-pressed={lookback === n}
                onClick={() => setLookback(n)}
              >
                {n}m
              </button>
            ))}
          </nav>
          {error && <p role="status">{error}</p>}
          {!snapshot && !error && <p>Connecting…</p>}
          {snapshot && (
            <>
              <span className="wt-badge">Research · execution disabled</span>
              <dl>
                <dt>Feed</dt>
                <dd>
                  {snapshot.connection} · {fresh ? "fresh" : "stale"}
                </dd>
                <dt>BTC/USD midpoint</dt>
                <dd data-testid="shared-quote">
                  {fresh && d.quote !== null
                    ? d.quote.toFixed(2)
                    : "Unavailable"}
                </dd>
                <dt>Return / realized volatility</dt>
                <dd>
                  {fresh && d.metrics
                    ? `${d.metrics.returnBps} bps / ${d.metrics.realizedVolatilityBps} bps`
                    : "Unavailable · incomplete or stale data"}
                </dd>
                <dt>Late updates skipped (3m)</dt>
                <dd>{d.ignoredLateObservations ?? 0}</dd>
                <dt>Observed at</dt>
                <dd>{d.quoteEventAt ?? "Unavailable"}</dd>
                <dt>Source cursor</dt>
                <dd data-testid="shared-cursor">{snapshot.sourceCursor}</dd>
                <dt>Input digest</dt>
                <dd>
                  <code data-testid="shared-digest">{d.inputDigest}</code>
                </dd>
              </dl>
              {candles.length > 0 && (
                <svg
                  viewBox="0 0 700 160"
                  role="img"
                  aria-label="Shared BTC minute closes"
                  style={{ width: "100%", height: 160 }}
                >
                  {candles.map((c: any, i: number) => (
                    <circle
                      key={c.at}
                      cx={
                        20 +
                        ((Date.parse(c.at) - Date.parse(candles[0].at)) /
                          Math.max(
                            1,
                            Date.parse(candles.at(-1).at) -
                              Date.parse(candles[0].at),
                          )) *
                          660
                      }
                      cy={140 - ((c.midpoint - min) / span) * 120}
                      r={3}
                      fill="#27C5DA"
                    >
                      <title>
                        {c.at}: {c.midpoint}
                      </title>
                    </circle>
                  ))}
                </svg>
              )}
              <button
                onClick={() => {
                  const { chatContext: _privateContext, ...exported } =
                    snapshot;
                  const a = document.createElement("a");
                  const u = URL.createObjectURL(
                    new Blob([JSON.stringify(exported, null, 2)], {
                      type: "application/json",
                    }),
                  );
                  a.href = u;
                  a.download = "kraken-research.json";
                  a.click();
                  setTimeout(() => URL.revokeObjectURL(u), 1000);
                }}
              >
                Export shared snapshot
              </button>
              {onDiscuss && (
                <button
                  disabled={!fresh || !review}
                  onClick={() => {
                    if (fresh && review) onDiscuss(structuredClone(review));
                  }}
                >
                  Discuss research
                </button>
              )}
            </>
          )}
        </>
      )}
    </section>
  );
}
