// Share the exact consumer validation with trusted local read-service consumers.
// This adapter has no transport: its only two inputs are an already produced
// context and response. CLI consumers need no separate economic calculator.
export async function validateMiningReadResponse({context,operation,input,response,now=Date.now}){
 const paths={read:base,history:base+'/history',receipt:base+'/receipt',treasuryReceipt:base+'/treasury-receipt',operatingReceipt:base+'/operating-receipt'};
 need(Object.hasOwn(paths,operation),'Unsupported validation operation');
 const client=createMiningReadClient({now,fetcher:async(path,options)=>{
  if(path===base+'/context'&&options.method==='GET')return Response.json(context);
  need(path===paths[operation]&&options.method==='POST'&&equal(JSON.parse(options.body),input),'Unexpected validation request');
  return Response.json(response);
 }});
 return client[operation](input);
}
