import {
  acceptStrategy,
  reconcile,
  type Bundle,
  type Version,
} from "./research.js";

export type CatalogueEntry = {
  version: Version;
  name: string;
  asset: string;
  thesis: string;
  horizonMinutes: number;
  evidence: Bundle["scope"]["evidence"][];
  document: ReturnType<typeof acceptStrategy>;
};
export type CatalogueFilters = Partial<
  Record<
    "query" | "asset" | "thesis" | "horizon" | "evidence" | "origin",
    string
  >
>;
const order = (a: string, b: string) => (a < b ? -1 : a > b ? 1 : 0);

// Index accepted original bytes, never a mutable envelope title or inferred ticker.
export function catalogue(
  versions: Version[],
  bundles: Bundle[],
): CatalogueEntry[] {
  const evidence = new Map<string, Set<Bundle["scope"]["evidence"]>>();
  for (const b of bundles) {
    for (const row of reconcile(b.rows)) {
      if (row.finality === "reverted") continue;
      const set = evidence.get(row.strategyDigest) ?? new Set();
      set.add(b.scope.evidence);
      evidence.set(row.strategyDigest, set);
    }
  }
  return [...new Map(versions.map((v) => [v.digest, v])).values()]
    .map((version) => {
      const document = acceptStrategy(version.raw);
      return {
        version,
        document,
        name: document.name,
        asset: document.market.assetMint,
        thesis: document.research.thesis,
        horizonMinutes: document.research.horizonMinutes,
        evidence: [...(evidence.get(version.digest) ?? [])].sort(order),
      };
    })
    .sort(
      (a, b) =>
        (Date.parse(b.version.createdAt) || 0) -
          (Date.parse(a.version.createdAt) || 0) ||
        order(a.version.digest, b.version.digest),
    );
}

export function filterCatalogue(
  entries: CatalogueEntry[],
  filters: CatalogueFilters,
) {
  const words = (filters.query ?? "")
    .trim()
    .toLowerCase()
    .split(/\s+/)
    .filter(Boolean);
  return entries.filter((e) => {
    const searchable = [
      e.name,
      e.document.description,
      e.version.digest,
      e.asset,
      e.thesis,
      e.horizonMinutes,
      e.version.origin,
      ...e.evidence,
    ]
      .join(" ")
      .toLowerCase();
    return (
      words.every((word) => searchable.includes(word)) &&
      (!filters.asset || filters.asset === e.asset) &&
      (!filters.thesis || filters.thesis === e.thesis) &&
      (!filters.horizon || filters.horizon === String(e.horizonMinutes)) &&
      (!filters.origin || filters.origin === e.version.origin) &&
      (!filters.evidence ||
        (filters.evidence === "none"
          ? e.evidence.length === 0
          : e.evidence.includes(
              filters.evidence as Bundle["scope"]["evidence"],
            )))
    );
  });
}
