import React from 'react';
import data from './mining-preview.json';
import {units} from './state.js';
import type {PreviewDisplay} from './useMiningPreview.js';
export type MiningPhaseCase = 'bootstrap'|'normal-empty-stake'|'normal-eligible';
export const phaseCases:Record<MiningPhaseCase,string>={bootstrap:'Bootstrap','normal-empty-stake':'Normal · no eligible stake','normal-eligible':'Normal · eligible stake'};
export function MiningPhaseSelector({value,onChange}:{value:MiningPhaseCase;onChange:(value:MiningPhaseCase)=>void}){
 return <label className="wt-phase">Settlement fixture<select aria-label="Settlement fixture" value={value} onChange={e=>onChange(e.target.value as MiningPhaseCase)}>{Object.entries(phaseCases).map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label>;
}
export function MiningPreview({phase,matched,load,dynamic}:{phase:MiningPhaseCase;matched:boolean;load?:()=>void;dynamic?:PreviewDisplay}){
 const scenario=dynamic?.envelope??data.scenarios.find(s=>s.name===phase);
 if(dynamic&&!dynamic.envelope)return <div className="wt-empty" aria-live="polite">{dynamic.status==='loading'?'Calculating canonical preview…':dynamic.error??'Enter a valid allocation to calculate.'}<button onClick={dynamic.refresh} disabled={dynamic.status==='loading'}>Calculate preview</button></div>;
 if((!dynamic&&!matched)||!scenario)return <div className="wt-empty">No canonical payout fixture for this allocation.{load?<button onClick={load}>Load 5 SOL Wide fixture</button>:null}</div>;
 const {response}=scenario;
 return <section className="wt-mining-preview" aria-label="Canonical mining preview" data-phase={phase}>
 <div className="wt-heading"><h3>{phaseCases[phase]}</h3><span className="wt-tag">Local conditional fixture · outcome {response.outcome===null?'invalid':'ABCDE'[response.outcome]}</span></div>
 <div className="wt-table-scroll" tabIndex={0} aria-label="Conditional returns"><table><thead><tr><th>Range</th><th>Committed SOL</th><th>Principal SOL</th><th>Staking refund SOL</th><th>Total returned SOL</th><th>Deduction / fee SOL</th><th>Miner BTC funding SOL</th><th>Miner SAT</th><th>LP SAT</th></tr></thead><tbody>{response.receipts.map(r=><tr key={r.ordinal}><th scope="row">{'ABCDE'[r.selection??0]}</th><td>{units(r.amount)}</td><td>{units(r.principal)}</td><td>{units(r.stakingRefund)}</td><td>{units(r.totalSolReturn)}</td><td>{units(r.forfeiture)} / {units(r.winnerFee)}</td><td>{units(r.minerInput)}</td><td>{units(r.sat)}</td><td>{units(r.lpSatContribution)}</td></tr>)}</tbody></table></div>
 <dl className="wt-facts"><div><dt>BTC paid</dt><dd>Unavailable · conversion not executed</dd></div><div><dt>LP SOL contribution</dt><dd>{units(response.receipts.reduce((n,r)=>(BigInt(n)+BigInt(r.lpSolContribution)).toString(),'0'))} SOL</dd></div><div><dt>Execution</dt><dd>Disabled</dd></div></dl>
 {dynamic?<div className="wt-heading"><span className="wt-tag">Review expires with context</span><button onClick={dynamic.refresh}>Recalculate</button></div>:null}<details><summary>Source and assumptions</summary><p>{dynamic?'Your selected entries only; no outside participants.':'Five separate 1 SOL entries, one in each range.'} Supplied state, BTC prices and crowding are fixtures. These are conditional entitlements, not paid rewards or a wallet balance.</p><code>{scenario.inputSHA256}</code><p>Canonical v2 accounting and issuance schedule. Bootstrap and normal returns use their own terms.</p></details>
 </section>;
}
