import React,{useState} from 'react';
import data from './mining-records.json';
import {units} from './state.js';
const btc=(value:string)=>{const n=BigInt(value);return `${n/100000000n}.${(n%100000000n).toString().padStart(8,'0')}`};
const short=(value:string)=>`${value.slice(0,6)}…${value.slice(-6)}`;
export function MiningRecords(){
 const [selected,setSelected]=useState(data.snapshots[0]?.id??'');
 const snapshot=data.snapshots.find(x=>x.id===selected);
 if(!snapshot)return <div className="wt-empty">No verified local records</div>;
 return <section className="wt-mining-preview" aria-label="Canonical local records">
 <label className="wt-phase">Recorded case<select aria-label="Recorded case" value={selected} onChange={e=>setSelected(e.target.value)}>{data.snapshots.map(x=><option key={x.id} value={x.id}>{x.id}</option>)}</select></label>
 <span className="wt-tag">Local bank evidence · not wallet history</span>
 <details><summary>Asset identity and source</summary><dl className="wt-facts"><div><dt>Mint</dt><dd><code>{snapshot.assetMint}</code></dd></div><div><dt>Program / economy / terms</dt><dd><code>{JSON.stringify(snapshot.binding)}</code></dd></div><div><dt>Source digest</dt><dd><code>{snapshot.inputSHA256}</code></dd></div></dl></details>
 {snapshot.rounds.length>0?<div className="wt-table-scroll" tabIndex={0} aria-label="Recorded rounds"><table><thead><tr><th>Round</th><th>Phase</th><th>State</th><th>Accepted SOL</th></tr></thead><tbody>{snapshot.rounds.map((r,i)=><tr key={i}><td>{r.slot}</td><td>{r.phase}</td><td>{['Open','Calculating','Apportioning','Finalized'][r.stage]??'Unknown'}</td><td>{units(r.acceptedLamports)}</td></tr>)}</tbody></table></div>:null}
 {snapshot.entries.length>0?<><h3>Principal and SAT claims</h3><div className="wt-table-scroll" tabIndex={0} aria-label="Recorded owner claims"><table><thead><tr><th>Round / owner</th><th>Committed SOL</th><th>Principal paid SOL</th><th>Staking refund earned / paid SOL</th><th>SAT earned / claimed</th></tr></thead><tbody>{snapshot.entries.map((e,i)=><tr key={i}><th scope="row">{e.slot} / <span title={e.owner}>{short(e.owner)}</span></th><td>{units(e.committedLamports)}</td><td>{units(e.principalReturnedLamports)}</td><td>{units(e.stakingRefundLamports)} / {units(e.stakingRefundReturnedLamports)}</td><td>{units(e.satAwardedAtoms)} / {units(e.satClaimedAtoms)}</td></tr>)}</tbody></table></div></>:null}
 {snapshot.payouts.length>0?<><h3>BTC conversions and payouts</h3><div className="wt-table-scroll" tabIndex={0} aria-label="Recorded BTC payouts"><table><thead><tr><th>Round / owner</th><th>Pending input SOL</th><th>Recovered SOL</th><th>BTC acquired</th><th>BTC paid</th><th>BTC unclaimed</th></tr></thead><tbody>{snapshot.payouts.map((p,i)=><tr key={i}><th scope="row">{p.slot} / <span title={p.owner}>{short(p.owner)}</span></th><td>{units(p.pendingConversionLamports)}</td><td>{units(p.recoveredLamports)}</td><td>{btc(p.btcAcquiredAtoms)}</td><td>{btc(p.btcPaidAtoms)}</td><td>{btc(p.btcUnclaimedAtoms)}</td></tr>)}</tbody></table></div></>:null}
 {snapshot.treasuryStates.map((t,i)=><section key={i}><h3>Treasury custody</h3><dl className="wt-facts"><div><dt>Held BTC</dt><dd>{btc(t.btcHeldAtoms)}</dd></div><div><dt>Locked SAT</dt><dd>{units(t.lockedSatAtoms)}</dd></div><div><dt>LP inventory SAT</dt><dd>{units(t.liquiditySatAtoms)}</dd></div><div><dt>LP inventory SOL / wrapped SOL</dt><dd>{units(t.liquiditySolLamports)} / {units(t.liquidityWrappedLamports)}</dd></div></dl></section>)}
 {snapshot.treasuryOrders.length>0?<><h3>Treasury orders</h3><div className="wt-table-scroll" tabIndex={0} aria-label="Recorded treasury orders"><table><thead><tr><th>Day / hour</th><th>Route</th><th>State</th><th>Attempts</th><th>Protocol LP receipts</th></tr></thead><tbody>{snapshot.treasuryOrders.map((o,i)=><tr key={i}><td>{o.day} / {o.hour}</td><td>{o.side===0?'Locked SAT buyback':'SAT/SOL liquidity'}</td><td>{['Reserved','Executed','Expired'][o.phase]??'Unknown'}</td><td>{o.attempts}</td><td>{BigInt(o.lp_burned)>0n?'Burned':'None'}</td></tr>)}</tbody></table></div></>:null}
 <p>Each case has its own source state. These records are not combined into a portfolio balance. No claim or signing action is enabled.</p>
 </section>;
}
